    private RunResult runIndexImage(String... arguments) {
        capturedOut.reset();
        capturedErr.reset();

        try {
            IndexImage.main(arguments);
            return new RunResult(0, capturedText(capturedOut), capturedText(capturedErr));
        }
        catch (ExitStatusException e) {
            return new RunResult(e.getStatus(), capturedText(capturedOut), capturedText(capturedErr));
        }
    }

    private static String capturedText(ByteArrayOutputStream stream) {
        return new String(stream.toByteArray(), StandardCharsets.UTF_8);
    }

    private void assertUsageExit(RunResult result) {
        assertEquals(5, result.status, result.stderr);
        assertTrue(result.stderr.contains("Usage: IndexImage"), result.stderr);
        assertTrue(result.stderr.contains("Input format names:"), result.stderr);
        assertTrue(result.stderr.contains("Output format names:"), result.stderr);
    }

    private Path writeColorfulPng(String fileName) throws IOException {
        BufferedImage image = new BufferedImage(8, 4, BufferedImage.TYPE_INT_ARGB);
        int[] colors = {RED, GREEN, BLUE, YELLOW, CYAN, MAGENTA, 0xFFFFFFFF, 0xFF000000};

        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                image.setRGB(x, y, colors[(x + y * image.getWidth()) % colors.length]);
            }
        }

        return writePng(fileName, image);
    }

    private Path writePng(String fileName, BufferedImage image) throws IOException {
        Path file = tempDir.resolve(fileName);
        assertTrue(ImageIO.write(image, "png", file.toFile()), "The test environment should have a PNG writer");
        return file;
    }

    private IndexColorModel assertIndexedOutput(Path output, int expectedWidth, int expectedHeight) throws IOException {
        return (IndexColorModel) assertIndexedOutputImage(output, expectedWidth, expectedHeight).getColorModel();
    }

    private BufferedImage assertIndexedOutputImage(Path output, int expectedWidth, int expectedHeight) throws IOException {
        assertTrue(Files.isRegularFile(output), "Expected output file " + output);
        BufferedImage image = ImageIO.read(output.toFile());
        assertNotNull(image, "Expected the output to contain a readable image");

        assertEquals(expectedWidth, image.getWidth());
        assertEquals(expectedHeight, image.getHeight());
        assertTrue(image.getColorModel() instanceof IndexColorModel,
                "Expected an indexed color model, but was " + image.getColorModel());
        return image;
    }

    private static Set<Integer> usedRgbColors(BufferedImage image) {
        Set<Integer> used = new HashSet<>();
        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                used.add(image.getRGB(x, y) & 0xFFFFFF);
            }
        }
        return used;
    }

    private static final class RunResult {
        private final int status;
        private final String stdout;
        private final String stderr;

        private RunResult(int status, String stdout, String stderr) {
            this.status = status;
            this.stdout = stdout;
            this.stderr = stderr;
        }
    }

    private static final class ExitStatusException extends SecurityException {
        private static final long serialVersionUID = 1L;

        private final int status;

        private ExitStatusException(int status) {
            super("System.exit(" + status + ")");
            this.status = status;
        }

        private int getStatus() {
            return status;
        }
    }

    private static final class NoExitSecurityManager extends SecurityManager {
        @Override
        public void checkExit(int status) {
            throw new ExitStatusException(status);
        }

        @Override
        public void checkPermission(Permission permission) {
            // Deliberately permissive: only System.exit is intercepted.
        }

        @Override
        public void checkPermission(Permission permission, Object context) {
            // Deliberately permissive: only System.exit is intercepted.
        }
    }
