        assertTrue(warnings.isEmpty(), "No warnings expected, was: " + warnings);
    }

    @Test
    public void testReadAbortedBeforeReadOnlyReadsFirstRow() throws IOException {
        byte[] file = bmp(2, 4, 24, DIB.COMPRESSION_RGB, 0, null, pixels(2, 24,
                new int[]{RED, RED},         // rows given top first...
                new int[]{GREEN, GREEN},
                new int[]{BLUE, BLUE},
                new int[]{WHITE, WHITE}), null, false);

        final int[] aborts = {0};
        reader.addIIOReadProgressListener(new ProgressListenerBase() {
            @Override
            public void readAborted(ImageReader source) {
                aborts[0]++;
            }
        });

        reader.setInput(imageInputStream(file));
        reader.abort();

        BufferedImage image = reader.read(0, null);

        assertEquals(1, aborts[0], "Expected exactly one abort event");
        assertEquals(4, image.getHeight());

        // Only the first (bottom) row was decoded before the loop broke, the rest is untouched
        assertEquals(argb(WHITE), image.getRGB(0, 3));
        assertEquals(argb(WHITE), image.getRGB(1, 3));
        assertEquals(0xFF000000, image.getRGB(0, 0));
        assertEquals(0xFF000000, image.getRGB(0, 2));
    }

    @Test
    public void testReadAbortedByProgressListener() throws IOException {
        byte[] file = bmp(2, 4, 24, DIB.COMPRESSION_RGB, 0, null, pixels(2, 24,
                new int[]{RED, RED},
                new int[]{GREEN, GREEN},
                new int[]{BLUE, BLUE},
                new int[]{WHITE, WHITE}), null, false);

        final int[] progress = {0};
        final int[] aborts = {0};

        reader.addIIOReadProgressListener(new ProgressListenerBase() {
            @Override
            public void imageProgress(ImageReader source, float percentageDone) {
                progress[0]++;
                source.abort();
            }

            @Override
            public void readAborted(ImageReader source) {
                aborts[0]++;
            }
        });

        BufferedImage image = read(file);

        assertEquals(1, progress[0], "Expected exactly one progress event before aborting");
        assertEquals(1, aborts[0], "Expected exactly one abort event");
        assertEquals(4, image.getHeight());
        assertEquals(0xFF000000, image.getRGB(0, 0));
    }

    @Test
    public void testReadTwiceYieldsSamePixels() throws IOException {
        byte[] file = pattern24Bit(3, 3);

        reader.setInput(imageInputStream(file));

        BufferedImage first = reader.read(0, null);
        BufferedImage second = reader.read(0, null);

        assertNotNull(first);
        assertNotNull(second);

        for (int y = 0; y < 3; y++) {
            for (int x = 0; x < 3; x++) {
                assertEquals(argb(pattern(x, y)), first.getRGB(x, y));
                assertEquals(first.getRGB(x, y), second.getRGB(x, y));
            }
        }
    }

