    private static ImageInputStream imageInputStream(byte[] file) {
        return new ByteArrayImageInputStream(file);
    }

    private static int argb(int rgb) {
        return 0xFF000000 | rgb;
    }

    /** Pixel pattern used by the region/subsampling tests. Unique per x/y coordinate. */
    private static int pattern(int x, int y) {
        return (x * 16 + 1) << 16 | (y * 16 + 1) << 8 | 0x40;
    }

    private static byte[] pattern24Bit(int width, int height) {
        int[][] rows = new int[height][width];
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                rows[y][x] = pattern(x, y);
            }
        }

        return bmp(width, height, 24, DIB.COMPRESSION_RGB, 0, null, pixels(width, 24, rows), null, false);
    }

    private static int rowSize(int width, int bitCount) {
        return ((bitCount * width + 31) / 32) * 4;
    }

    /** Builds the raw pixel data as stored in the file, rows in top-first order are reversed (bottom-up). */
    private static byte[] pixels(int width, int bitCount, int[]... rowsTopFirst) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int i = rowsTopFirst.length - 1; i >= 0; i--) {
            byte[] row = row(width, bitCount, rowsTopFirst[i]);
            out.write(row, 0, row.length);
        }

        return out.toByteArray();
    }

    /** Builds the raw pixel data for a top-down bitmap: rows are stored in image order. */
    private static byte[] pixelsTopDown(int width, int bitCount, int[]... rowsTopFirst) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int[] samples : rowsTopFirst) {
            byte[] row = row(width, bitCount, samples);
            out.write(row, 0, row.length);
        }

        return out.toByteArray();
    }

    /**
     * Encodes one padded scan line.
     * <p>
     * For 24 bit the samples are {@code 0xRRGGBB} values, for 32/16 bit they are the raw
     * little endian words, for 8/4/2/1 bit they are palette indices.
     * </p>
     */
    private static byte[] row(int width, int bitCount, int[] samples) {
        if (samples.length != width) {
            throw new IllegalArgumentException("Expected " + width + " samples, got " + samples.length);
        }

        byte[] row = new byte[rowSize(width, bitCount)];

        switch (bitCount) {
            case 1:
            case 2:
            case 4: {
                int perByte = 8 / bitCount;
                int mask = (1 << bitCount) - 1;
                for (int x = 0; x < width; x++) {
                    int shift = 8 - bitCount - (x % perByte) * bitCount;
                    row[x / perByte] |= (byte) ((samples[x] & mask) << shift);
                }
                break;
            }
            case 8:
                for (int x = 0; x < width; x++) {
                    row[x] = (byte) samples[x];
                }
                break;
            case 16:
                for (int x = 0; x < width; x++) {
                    row[x * 2] = (byte) samples[x];
                    row[x * 2 + 1] = (byte) (samples[x] >>> 8);
                }
                break;
            case 24:
                for (int x = 0; x < width; x++) {
                    row[x * 3] = (byte) samples[x];              // B
                    row[x * 3 + 1] = (byte) (samples[x] >>> 8);  // G
                    row[x * 3 + 2] = (byte) (samples[x] >>> 16); // R
                }
                break;
            case 32:
                for (int x = 0; x < width; x++) {
                    putIntLE(row, x * 4, samples[x]);
                }
                break;
            default:
                throw new IllegalArgumentException("Unsupported bitCount: " + bitCount);
        }

        return row;
    }

    /**
     * Builds a minimal BMP file with a BITMAPINFOHEADER (40 bytes).
     *
     * @param palette 0xRRGGBB palette entries, or {@code null}
     * @param masks   bit field masks, or {@code null}
     */
    private static byte[] bmp(int width, int height, int bitCount, int compression,
                              int colorsUsed, int[] palette, byte[] pixelData,
                              int[] masks, boolean topDown) {
        int maskBytes = masks == null ? 0 : masks.length * 4;
        int paletteBytes = palette == null ? 0 : palette.length * 4;
        int offBits = DIB.BMP_FILE_HEADER_SIZE + DIB.BITMAP_INFO_HEADER_SIZE + maskBytes + paletteBytes;

        byte[] file = new byte[offBits + pixelData.length];

        // BITMAPFILEHEADER
        file[0] = 'B';
        file[1] = 'M';
        putIntLE(file, 2, file.length); // file size
        putIntLE(file, 6, 0);           // reserved
        putIntLE(file, 10, offBits);    // pixel array offset

        // BITMAPINFOHEADER
        putIntLE(file, 14, DIB.BITMAP_INFO_HEADER_SIZE);
        putIntLE(file, 18, width);
        putIntLE(file, 22, topDown ? -height : height);
        putShortLE(file, 26, 1);        // planes
        putShortLE(file, 28, bitCount);
        putIntLE(file, 30, compression);
        putIntLE(file, 34, pixelData.length); // image size
        putIntLE(file, 38, 2835);       // x pixels per meter
        putIntLE(file, 42, 2835);       // y pixels per meter
        putIntLE(file, 46, colorsUsed);
        putIntLE(file, 50, 0);          // colors important

        int offset = 54;
        if (masks != null) {
            for (int mask : masks) {
                putIntLE(file, offset, mask);
                offset += 4;
            }
        }
        if (palette != null) {
            for (int color : palette) {
                putIntLE(file, offset, color & 0xFFFFFF);
                offset += 4;
            }
        }

        System.arraycopy(pixelData, 0, file, offset, pixelData.length);

        return file;
    }

    private static void putIntLE(byte[] bytes, int offset, int value) {
        bytes[offset] = (byte) value;
        bytes[offset + 1] = (byte) (value >>> 8);
        bytes[offset + 2] = (byte) (value >>> 16);
        bytes[offset + 3] = (byte) (value >>> 24);
    }

    private static void putShortLE(byte[] bytes, int offset, int value) {
        bytes[offset] = (byte) value;
        bytes[offset + 1] = (byte) (value >>> 8);
    }
}

