    @Test
    void decodeWithRestartInterval() throws IOException {
        // 4x1 image with a restart interval of 2. The prediction is reset to 2^(8-0-1) = 128 at the
        // start of each restart interval, so both intervals decode to 128+1 = 129, 129+1 = 130.
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_7, new int[]{1}))
                .segment(JPEG.DRI, new byte[]{0x00, 0x02})
