                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(0x01, 0x01)
                .bytes(0xFF, 0xD0) // RST0
                .bytes(0x01, 0x01)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg);

        assertEquals(1, result.length);
        assertArrayEquals(new int[]{129, 130, 129, 130}, result[0]);
    }

