    @Test
    void decodeMasksSamplesToEightBitPrecision() throws IOException {
        // A 130x1, 8 bit image where every difference is -1: the prediction runs from 127 down to 0
        // and then wraps around, as the samples are 8 bit values (masked with 0xFF)
        int[] entropyData = new int[200];

        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_7, new int[]{1}))
                .segment(JPEG.SOF3, sof(8, 130, 1, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(entropyData)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg);

        assertEquals(1, result.length);
        assertEquals(130, result[0].length);
        assertEquals(127, result[0][0]);
        assertEquals(1, result[0][126]);
        assertEquals(0, result[0][127]);
        assertEquals(255, result[0][128]);
        assertEquals(254, result[0][129]);
    }

