    private static JPEGLosslessDecoder newDecoder(byte[] jpeg) throws IOException {
        return newDecoder(parseSegments(jpeg), jpeg, null);
    }

    private static JPEGLosslessDecoder newDecoder(List<Segment> segments, byte[] data, JPEGImageReader listenerDelegate) {
        ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));

        return new JPEGLosslessDecoder(segments, input, listenerDelegate);
    }

    private static int[][] decode(byte[] jpeg) throws IOException {
        return decode(parseSegments(jpeg), jpeg, null);
    }

    private static int[][] decode(byte[] jpeg, JPEGImageReader listenerDelegate) throws IOException {
        return decode(parseSegments(jpeg), jpeg, listenerDelegate);
    }

    private static int[][] decode(List<Segment> segments, byte[] data, JPEGImageReader listenerDelegate) throws IOException {
        ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));

        try {
            return new JPEGLosslessDecoder(segments, input, listenerDelegate).decode();
        }
        finally {
            input.close();
        }
    }

    private static JPEGImageReader warningCollectingReader(final List<String> warnings) {
        JPEGImageReader reader = new JPEGImageReader(new JPEGImageReaderSpi(), mock(ImageReader.class));
        reader.addIIOReadWarningListener(new IIOReadWarningListener() {
            @Override
            public void warningOccurred(ImageReader source, String warning) {
                warnings.add(warning);
            }
        });

        return reader;
    }

    private static List<Segment> parseSegments(byte[] jpeg) throws IOException {
        List<Segment> segments = new ArrayList<>();
        DataInputStream stream = new DataInputStream(new ByteArrayInputStream(jpeg));

        assertEquals(JPEG.SOI, stream.readUnsignedShort(), "Test stream does not start with SOI");

        while (true) {
            int marker = stream.readUnsignedShort();

            if (marker == JPEG.SOS || marker == JPEG.EOI) {
                return segments;
            }

            int length = stream.readUnsignedShort();
            byte[] payload = new byte[length - 2];
            stream.readFully(payload);

            segments.add(Segment.read(marker, "", length, new DataInputStream(new ByteArrayInputStream(payload))));
        }
    }

    private static byte[] dht(int tableClass, int tableId, int[] codeLengthCounts, int[] values) {
        byte[] payload = new byte[1 + 16 + values.length];
        payload[0] = (byte) ((tableClass << 4) | tableId);

        for (int i = 0; i < 16; i++) {
            payload[1 + i] = (byte) codeLengthCounts[i];
        }

        for (int i = 0; i < values.length; i++) {
            payload[1 + 16 + i] = (byte) values[i];
        }

        return payload;
    }

    private static byte[] sof(int precision, int width, int height, int[][] components) {
        // Each component is {id, hSub, vSub, qtSel}
        byte[] payload = new byte[6 + components.length * 3];
        payload[0] = (byte) precision;
        payload[1] = (byte) (height >> 8);
        payload[2] = (byte) height;
        payload[3] = (byte) (width >> 8);
        payload[4] = (byte) width;
        payload[5] = (byte) components.length;

        for (int i = 0; i < components.length; i++) {
            payload[6 + i * 3] = (byte) components[i][0];
            payload[7 + i * 3] = (byte) ((components[i][1] << 4) | components[i][2]);
            payload[8 + i * 3] = (byte) components[i][3];
        }

        return payload;
    }

    private static byte[] sos(int[][] components, int spectralSelStart, int spectralSelEnd, int approxHigh, int approxLow) {
        // Each component is {scanCompSel, dcTabSel, acTabSel}
        byte[] payload = new byte[4 + components.length * 2];
        payload[0] = (byte) components.length;

        for (int i = 0; i < components.length; i++) {
            payload[1 + i * 2] = (byte) components[i][0];
            payload[2 + i * 2] = (byte) ((components[i][1] << 4) | components[i][2]);
        }

        int index = 1 + components.length * 2;
        payload[index] = (byte) spectralSelStart;
        payload[index + 1] = (byte) spectralSelEnd;
        payload[index + 2] = (byte) ((approxHigh << 4) | approxLow);

        return payload;
    }

    /** Simple builder for JPEG streams. */
    private static final class JpegStream {
        private final ByteArrayOutputStream out = new ByteArrayOutputStream();

        JpegStream soi() {
            return marker(JPEG.SOI);
        }

        JpegStream eoi() {
            return marker(JPEG.EOI);
        }

        JpegStream marker(int marker) {
            out.write((marker >> 8) & 0xFF);
            out.write(marker & 0xFF);

            return this;
        }

        JpegStream segment(int marker, byte[] payload) {
            marker(marker);

            int length = payload.length + 2;
            out.write((length >> 8) & 0xFF);
            out.write(length & 0xFF);
            out.write(payload, 0, payload.length);

            return this;
        }

        JpegStream bytes(int... values) {
            for (int value : values) {
                out.write(value & 0xFF);
            }

            return this;
        }

        byte[] toByteArray() {
            return out.toByteArray();
        }
    }
