            palette[1 + i * 3] = (byte) i;
            palette[2 + i * 3] = (byte) (255 - i);
            palette[3 + i * 3] = (byte) (i / 2);
        }

        byte[] pcx = createPCX(PCX.VERSION_3, PCX.COMPRESSION_NONE, 8, 1, width, height, width, defaultEGAPalette(), data);
        byte[] withPalette = Arrays.copyOf(pcx, pcx.length + palette.length);
        System.arraycopy(palette, 0, withPalette, pcx.length, palette.length);

        PCXImageReader reader = newReader(withPalette);

        IndexColorModel colorModel = assertInstanceOf(IndexColorModel.class, reader.getRawImageType(0).getColorModel());
        assertEquals(256, colorModel.getMapSize());

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_BYTE_INDEXED, image.getType());
        assertEquals(vgaColor(0), image.getRGB(0, 0));
        assertEquals(vgaColor(5), image.getRGB(1, 0));
        assertEquals(vgaColor(200), image.getRGB(2, 0));
        assertEquals(vgaColor(0), image.getRGB(3, 0));
        assertEquals(vgaColor(7), image.getRGB(1, 1));
    }

