        assertEquals(width, image.getWidth());
        assertEquals(height, image.getHeight());
        assertEquals(1, listener.progress.size(), "Reading should stop after the first scan line");
        assertTrue(listener.events.contains("imageAborted"), listener.events.toString());
        assertTrue(listener.events.indexOf("imageAborted") < listener.events.indexOf("imageComplete"), listener.events.toString());
