    private PCXImageReader newReaderForResource(String resource) throws IOException {
        return newReader(new ByteArrayImageInputStream(resourceBytes(resource)));
    }

    private PCXImageReader newReader(byte[] pcx) {
        return newReader(new ByteArrayImageInputStream(pcx));
    }

    private PCXImageReader newReader(ImageInputStream input) {
        PCXImageReader reader = new PCXImageReader(new PCXImageReaderSpi());
        reader.setInput(input);
        readers.add(reader);
        return reader;
    }

    private byte[] resourceBytes(String resource) throws IOException {
        InputStream input = getClass().getResourceAsStream("/" + resource);
        assertNotNull(input, "Missing test resource: " + resource);

        try {
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            byte[] buffer = new byte[1024];
            int read;

            while ((read = input.read(buffer)) > 0) {
                bytes.write(buffer, 0, read);
            }

            return bytes.toByteArray();
        }
        finally {
            input.close();
        }
    }

    private static byte[] defaultEGAPalette() {
        byte[] palette = new byte[48];
        for (int i = 0; i < 16; i++) {
            palette[i * 3] = (byte) (i * 16);
            palette[i * 3 + 1] = (byte) (255 - i * 16);
            palette[i * 3 + 2] = (byte) (i * 8);
        }

        return palette;
    }

    private static int vgaColor(int index) {
        return 0xFF000000 | index << 16 | (255 - index) << 8 | index / 2;
    }

    private static byte[] createPCX(int version, int compression, int bitsPerPixel, int channels,
                                    int width, int height, int bytesPerLine, byte[] egaPalette, byte[] pixelData) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream(PCX.HEADER_SIZE + pixelData.length);
        DataOutputStream out = new DataOutputStream(bytes);

        out.writeByte(PCX.MAGIC);
        out.writeByte(version);
        out.writeByte(compression);
        out.writeByte(bitsPerPixel);
        writeLE16(out, 0);              // XStart
        writeLE16(out, 0);              // YStart
        writeLE16(out, width - 1);      // XEnd
        writeLE16(out, height - 1);     // YEnd
        writeLE16(out, 72);             // HorzRes
        writeLE16(out, 72);             // VertRes
        out.write(egaPalette);          // 48 byte EGA palette
        out.writeByte(0);               // Reserved
        out.writeByte(channels);
        writeLE16(out, bytesPerLine);
        writeLE16(out, PCX.PALETTEINFO_COLOR);
        writeLE16(out, width);          // HorzScreenSize
        writeLE16(out, height);         // VertScreenSize

        for (int i = 0; i < PCX.HEADER_SIZE - 74; i++) {
            out.writeByte(0);
        }

        out.flush();
        out.write(pixelData);
        out.flush();

        return bytes.toByteArray();
    }

    private static void writeLE16(DataOutputStream out, int value) throws IOException {
        out.writeByte(value & 0xFF);
        out.writeByte(value >> 8 & 0xFF);
    }

    private static int subsampledSize(int size, int sub, int offset) {
        return (size - offset + sub - 1) / sub;
    }

    private static int[] samples(BufferedImage image) {
        return samples(image, new Rectangle(0, 0, image.getWidth(), image.getHeight()));
    }

    private static int[] samples(BufferedImage image, Rectangle area) {
        return image.getRaster().getPixels(area.x, area.y, area.width, area.height, (int[]) null);
    }

    private static final class RecordingProgressListener implements IIOReadProgressListener {
        final List<String> events = new ArrayList<>();
        final List<Float> progress = new ArrayList<>();

        @Override
        public void sequenceStarted(ImageReader source, int minIndex) {
            events.add("sequenceStarted");
        }

        @Override
        public void sequenceComplete(ImageReader source) {
            events.add("sequenceComplete");
        }

        @Override
        public void imageStarted(ImageReader source, int imageIndex) {
            events.add("imageStarted");
        }

        @Override
        public void imageProgress(ImageReader source, float percentageDone) {
            events.add("imageProgress");
            progress.add(percentageDone);
        }

        @Override
        public void imageComplete(ImageReader source) {
            events.add("imageComplete");
        }

        @Override
        public void thumbnailStarted(ImageReader source, int imageIndex, int thumbnailIndex) {
            // No thumbnails
        }

        @Override
        public void thumbnailProgress(ImageReader source, float percentageDone) {
            // No thumbnails
        }

        @Override
        public void thumbnailComplete(ImageReader source) {
            // No thumbnails
        }

        @Override
        public void readAborted(ImageReader source) {
            events.add("imageAborted");
        }
    }
