package com.twelvemonkeys.imageio.plugins.psd;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import javax.imageio.IIOException;
import java.awt.HeadlessException;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.regex.Pattern;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Functional tests for the PSDImageReader command-line harness.
 *
 * <p>The harness ends by displaying the result in a Swing window. Tests run in
 * headless mode, so a successful image read is observed through the printed
 * image information followed by the expected {@link HeadlessException} from the
 * display attempt.</p>
 */
class PSDImageReaderMainTests {
    private static final Path PSD_5X5 = resourcePath("/psd/32bit5x5.psd");
    private static final Path MISSING_PSD = Paths.get("target", "definitely-missing-" + System.nanoTime() + ".psd");

    @TempDir
    Path tempDir;

    @Test
    void noArgumentsFailsWhileLookingForFirstOption() throws Exception {
        RunResult result = invokeMain();

        assertInstanceOf(ArrayIndexOutOfBoundsException.class, result.failure);
        assertEquals("", result.stdout);
        assertEquals("", result.stderr);
    }

    @Test
    void invalidSubsamplingValueFailsBeforeOpeningFile() throws Exception {
        RunResult result = invokeMain("-s", "not-a-number", PSD_5X5.toString());

        assertInstanceOf(NumberFormatException.class, result.failure);
        assertEquals("", result.stdout);
        assertEquals("", result.stderr);
    }

    @Test
    void defaultsReadAndPrintMergedPsdBeforeDisplayAttempt() throws Exception {
        RunResult result = invokeMain(PSD_5X5.toString());

        assertDisplayAttemptFailed(result);
        assertTrue(result.stdout.contains("file: " + PSD_5X5.toAbsolutePath()), result.stdout);
        assertTrue(result.stdout.contains(
                "imageReader.header: PSDHeader[version: 1, channels: 3, width: 5, height: 5, depth: 32, mode: 3 (RGB)]"
        ), result.stdout);
        assertTrue(result.stdout.contains("imageReader.imageResources: ["), result.stdout);
        assertTrue(result.stdout.contains("PSDThumbnail[ID: 0x40c, format: JPEG"), result.stdout);
        assertTrue(result.stdout.contains("imageReader.layerInfo: ["), result.stdout);
        assertTrue(result.stdout.contains("layer name: \"Background\""), result.stdout);
        assertTrue(Pattern.compile("(?m)^read time: \\d+$").matcher(result.stdout).find(), result.stdout);
        assertEquals(2, occurrences(result.stdout, "image: BufferedImage@"), result.stdout);
        assertTrue(result.stdout.contains("width = 5 height = 5"), result.stdout);
        assertFalse(result.stdout.contains("sourceRegion:"), result.stdout);
    }

    @Test
    void shortSubsamplingOptionChangesReadImageDimensions() throws Exception {
        RunResult result = invokeMain("-s", "2", PSD_5X5.toString());

        assertDisplayAttemptFailed(result);
        assertFalse(result.stdout.contains("sourceRegion:"), result.stdout);
        assertTrue(result.stdout.contains("width = 3 height = 3"), result.stdout);
    }

    @Test
    void longOptionsApplySubsamplingToExplicitSourceRegion() throws Exception {
        RunResult result = invokeMain(
                "--subsampling", "2",
                "--sourceregion", "1", "1", "2", "2",
                PSD_5X5.toString()
        );

        assertDisplayAttemptFailed(result);
        assertTrue(result.stdout.contains(
                "sourceRegion: java.awt.Rectangle[x=1,y=1,width=2,height=2]"
        ), result.stdout);
        assertTrue(result.stdout.contains("width = 1 height = 1"), result.stdout);
    }

    @Test
    void sourceRegionFallsBackToTwoDimensionsAtOrigin() throws Exception {
        RunResult result = invokeMain("-r", "3", "2", PSD_5X5.toString());

        assertDisplayAttemptFailed(result);
        assertTrue(result.stdout.contains(
                "sourceRegion: java.awt.Rectangle[x=0,y=0,width=3,height=2]"
        ), result.stdout);
        assertTrue(result.stdout.contains("width = 3 height = 2"), result.stdout);
    }

    @Test
    void thumbnailOptionsReadThumbnailBeforeMergedImage() throws Exception {
        for (String thumbnailOption : Arrays.asList("-t", "--thumbnails")) {
            RunResult result = invokeMain(thumbnailOption, PSD_5X5.toString());

            assertDisplayAttemptFailed(result, thumbnailOption);
            assertTrue(result.stdout.contains("imageReader.layerInfo: ["), result.stdout);
            assertFalse(result.stdout.contains("read time:"), result.stdout);
            assertFalse(result.stdout.contains("image: BufferedImage@"), result.stdout);
        }
    }

    @Test
    void layerOptionsAreAcceptedAndProceedToFileRead() throws Exception {
        for (String layerOption : Arrays.asList("-l", "--layers")) {
            ProcessResult result = invokeInSeparateJvm(layerOption, missingFile().toString());

            assertEquals(1, result.exitCode, layerOption + ": " + result.stderr);
            assertTrue(result.stdout.contains("file: " + missingFile().toAbsolutePath()), result.stdout);
            assertFalse(result.stderr.contains("Usage:"), result.stderr);
            assertTrue(result.stderr.contains("IllegalStateException: getInput() == null"), result.stderr);
        }
    }

    @Test
    void unknownOptionPrintsUsageAndExitsWithStatusOne() throws Exception {
        ProcessResult result = invokeInSeparateJvm("--not-a-real-option");

        assertEquals(1, result.exitCode);
        assertEquals("", result.stdout);
        assertEquals(
                "Usage: java PSDImageReader [-s <subsample factor>] [-r [<x y>] <w h>] [-t -l] <image file>"
                        + System.lineSeparator(),
                result.stderr
        );
    }

    @Test
    void missingFileFailsAfterPrintingFileBanner() throws Exception {
        Path missing = missingFile();
        RunResult result = invokeMain(missing.toString());

        assertInstanceOf(IllegalStateException.class, result.failure);
        assertEquals("getInput() == null", result.failure.getMessage());
        assertTrue(result.stdout.contains("file: " + missing.toAbsolutePath()), result.stdout);
        assertFalse(result.stdout.contains("imageReader.header:"), result.stdout);
    }

    @Test
    void invalidPsdFileFailsWhileReadingHeader() throws Exception {
        Path invalid = tempDir.resolve("invalid.psd");
        Files.write(invalid, "not a PSD".getBytes(StandardCharsets.US_ASCII));

        RunResult result = invokeMain(invalid.toString());

        assertInstanceOf(IIOException.class, result.failure);
        assertTrue(result.failure.getMessage().contains("Not a PSD document"), result.failure.getMessage());
        assertTrue(result.stdout.contains("file: " + invalid.toAbsolutePath()), result.stdout);
        assertFalse(result.stdout.contains("imageReader.header:"), result.stdout);
    }

    private Path missingFile() {
        return tempDir.resolve(MISSING_PSD.getFileName()).toAbsolutePath();
    }

    private static void assertDisplayAttemptFailed(RunResult result) {
        assertDisplayAttemptFailed(result, "default");
    }

    private static void assertDisplayAttemptFailed(RunResult result, String description) {
        assertNotNull(result.failure, description + " should attempt to display the result");
        assertInstanceOf(HeadlessException.class, result.failure, description + ": " + result.stdout);
    }

    private static int occurrences(String text, String needle) {
        int count = 0;
        int index = 0;
        while ((index = text.indexOf(needle, index)) != -1) {
            count++;
            index += needle.length();
        }
        return count;
    }

    private static RunResult invokeMain(String... args) throws Exception {
        assertTrue(java.awt.GraphicsEnvironment.isHeadless(), "The CLI harness tests require a headless JVM");

        PrintStream originalOut = System.out;
        PrintStream originalErr = System.err;
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        ByteArrayOutputStream err = new ByteArrayOutputStream();
        Throwable failure = null;

        try {
            System.setOut(new PrintStream(out, true, "UTF-8"));
            System.setErr(new PrintStream(err, true, "UTF-8"));
            PSDImageReader.main(args);
        }
        catch (Throwable t) {
            failure = t;
        }
        finally {
            System.setOut(originalOut);
            System.setErr(originalErr);
        }

        return new RunResult(out.toString("UTF-8"), err.toString("UTF-8"), failure);
    }

    private static ProcessResult invokeInSeparateJvm(String... args) throws Exception {
        String javaExecutable = Paths.get(System.getProperty("java.home"), "bin",
                System.getProperty("os.name").startsWith("Windows") ? "java.exe" : "java").toString();
        String classPath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));

        List<String> command = new ArrayList<>();
        command.add(javaExecutable);
        command.add("-Djava.awt.headless=true");
        command.add("-cp");
        command.add(classPath);
        command.add(PSDImageReader.class.getName());
        command.addAll(Arrays.asList(args));

        Process process = new ProcessBuilder(command).start();
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        ByteArrayOutputStream err = new ByteArrayOutputStream();
        copy(process.getInputStream(), out);
        copy(process.getErrorStream(), err);

        return new ProcessResult(process.waitFor(), out.toString("UTF-8"), err.toString("UTF-8"));
    }

    private static void copy(InputStream input, ByteArrayOutputStream output) throws IOException {
        byte[] buffer = new byte[4096];
        int read;
        while ((read = input.read(buffer)) != -1) {
            output.write(buffer, 0, read);
        }
    }

    private static Path resourcePath(String name) {
        URL resource = PSDImageReaderMainTests.class.getResource(name);
        if (resource == null) {
            throw new IllegalStateException("Missing test resource: " + name);
        }

        try {
            return Paths.get(resource.toURI());
        }
        catch (Exception e) {
            throw new IllegalStateException("Invalid test resource path: " + name, e);
        }
    }

    private static final class RunResult {
        final String stdout;
        final String stderr;
        final Throwable failure;

        RunResult(String stdout, String stderr, Throwable failure) {
            this.stdout = stdout;
            this.stderr = stderr;
            this.failure = failure;
        }
    }

    private static final class ProcessResult {
        final int exitCode;
        final String stdout;
        final String stderr;

        ProcessResult(int exitCode, String stdout, String stderr) {
            this.exitCode = exitCode;
            this.stdout = stdout;
            this.stderr = stderr;
        }
    }
}

