    private static TiffBuilder withoutPhotometric(int bitsPerSample, int samplesPerPixel) {
        return new TiffBuilder()
                .addLong(TIFF.TAG_IMAGE_WIDTH, 1)
                .addLong(TIFF.TAG_IMAGE_HEIGHT, 1)
                .addShort(TIFF.TAG_SAMPLES_PER_PIXEL, samplesPerPixel)
                .addShort(TIFF.TAG_BITS_PER_SAMPLE, repeat(bitsPerSample, samplesPerPixel));
    }

    private static int[] palette(int size) {
        int[] values = new int[size * 3];
        for (int i = 0; i < size; i++) {
            values[i] = size == 1 ? 0 : (i * 255) / (size - 1);
            values[size + i] = 255 - values[i];
            values[2 * size + i] = (i * 37) & 0xff;
        }
        return values;
    }

    private static byte[] iccProfile(int colorSpace) {
        return ICC_Profile.getInstance(colorSpace).getData();
    }

    private static TiffBuilder base(int photometricInterpretation, int bitsPerSample, int samplesPerPixel) {
        return new TiffBuilder()
                .addLong(TIFF.TAG_IMAGE_WIDTH, 1)
                .addLong(TIFF.TAG_IMAGE_HEIGHT, 1)
                .addShort(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, photometricInterpretation)
                .addShort(TIFF.TAG_SAMPLES_PER_PIXEL, samplesPerPixel)
                .addShort(TIFF.TAG_BITS_PER_SAMPLE, repeat(bitsPerSample, samplesPerPixel));
    }

    private static int[] repeat(int value, int count) {
        int[] values = new int[count];
        java.util.Arrays.fill(values, value);
        return values;
    }

    private static ImageTypeSpecifier readType(TiffBuilder tiff) throws IOException {
        return readType(tiff, new ArrayList<String>(), 0);
    }

    private static ImageTypeSpecifier readType(TiffBuilder tiff, List<String> warnings) throws IOException {
        return readType(tiff, warnings, 0);
    }

    private static ImageTypeSpecifier readType(TiffBuilder tiff, int imageIndex) throws IOException {
        return readType(tiff, new ArrayList<String>(), imageIndex);
    }

    private static ImageTypeSpecifier readType(TiffBuilder tiff, List<String> warnings, int imageIndex) throws IOException {
        byte[] data = tiff.build();
        try (ByteArrayImageInputStream input = new ByteArrayImageInputStream(data)) {
            TIFFImageReader reader = new TIFFImageReader(new TIFFImageReaderSpi());
            reader.setInput(input);
            reader.addIIOReadWarningListener((source, warning) -> warnings.add(warning));
            try {
                return reader.getRawImageType(imageIndex);
            }
            finally {
                reader.dispose();
            }
        }
    }

    private static final class TiffBuilder {
        private static final short TYPE_SHORT = 3;
        private static final short TYPE_LONG = 4;
        private static final short TYPE_UNDEFINED = 7;

        private final List<Entry> entries = new ArrayList<>();

        TiffBuilder addUndefined(int tag, byte... values) {
            entries.add(new Entry(tag, TYPE_UNDEFINED, values.length, values.clone()));
            return this;
        }

        TiffBuilder addShort(int tag, int... values) {
            return add(tag, TYPE_SHORT, values);
        }

        TiffBuilder addLong(int tag, long... values) {
            byte[] data = new byte[values.length * 4];
            int offset = 0;
            for (long value : values) {
                data[offset++] = (byte) value;
                data[offset++] = (byte) (value >>> 8);
                data[offset++] = (byte) (value >>> 16);
                data[offset++] = (byte) (value >>> 24);
            }
            entries.add(new Entry(tag, TYPE_LONG, values.length, data));
            return this;
        }

        private TiffBuilder add(int tag, short type, int... values) {
            byte[] data = new byte[values.length * (type == TYPE_SHORT ? 2 : 4)];
            int offset = 0;
            for (int value : values) {
                if (type == TYPE_SHORT) {
                    data[offset++] = (byte) value;
                    data[offset++] = (byte) (value >>> 8);
                }
                else {
                    data[offset++] = (byte) value;
                    data[offset++] = (byte) (value >>> 8);
                    data[offset++] = (byte) (value >>> 16);
                    data[offset++] = (byte) (value >>> 24);
                }
            }
            entries.add(new Entry(tag, type, values.length, data));
            return this;
        }

        byte[] build() {
            int ifdOffset = 8;
            int ifdSize = 2 + entries.size() * 12 + 4;
            int externalOffset = ifdOffset + ifdSize;
            int[] offsets = new int[entries.size()];

            for (int i = 0; i < entries.size(); i++) {
                Entry entry = entries.get(i);
                if (entry.data.length > 4) {
                    if ((externalOffset & 1) != 0) {
                        externalOffset++;
                    }
                    offsets[i] = externalOffset;
                    externalOffset += entry.data.length;
                }
            }

            byte[] bytes = new byte[externalOffset];
            bytes[0] = 'I';
            bytes[1] = 'I';
            putShort(bytes, 2, TIFF.TIFF_MAGIC);
            putInt(bytes, 4, ifdOffset);
            putShort(bytes, ifdOffset, entries.size());

            int entryOffset = ifdOffset + 2;
            for (int i = 0; i < entries.size(); i++) {
                Entry entry = entries.get(i);
                putShort(bytes, entryOffset, entry.tag);
                putShort(bytes, entryOffset + 2, entry.type);
                putInt(bytes, entryOffset + 4, entry.count);

                if (entry.data.length <= 4) {
                    System.arraycopy(entry.data, 0, bytes, entryOffset + 8, entry.data.length);
                }
                else {
                    putInt(bytes, entryOffset + 8, offsets[i]);
                    System.arraycopy(entry.data, 0, bytes, offsets[i], entry.data.length);
                }

                entryOffset += 12;
            }

            putInt(bytes, entryOffset, 0);
            return bytes;
        }

        private static void putShort(byte[] bytes, int offset, int value) {
            bytes[offset] = (byte) value;
            bytes[offset + 1] = (byte) (value >>> 8);
        }

        private static void putInt(byte[] bytes, int offset, int value) {
            bytes[offset] = (byte) value;
            bytes[offset + 1] = (byte) (value >>> 8);
            bytes[offset + 2] = (byte) (value >>> 16);
            bytes[offset + 3] = (byte) (value >>> 24);
        }

        private static final class Entry {
            final int tag;
            final short type;
            final int count;
            final byte[] data;

            Entry(int tag, short type, int count, byte[] data) {
                this.tag = tag;
                this.type = type;
                this.count = count;
                this.data = data;
            }
        }
    }
