package com.twelvemonkeys.imageio.plugins.webp.lossless;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.awt.image.DataBuffer;
import java.awt.image.Raster;
import java.awt.image.WritableRaster;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Tests for {@code PredictorTransform#applyInverse(WritableRaster)}.
 * <p>
 * The raster under test has interleaved 8 bit RGBA samples, ie. the data elements
 * returned by {@code getDataElements} are ordered red, green, blue, alpha.
 * All arithmetic in the inverse predictor is modulo 256 (unsigned byte arithmetic).
 */
class PredictorTransformApplyInverseTests {

    private static final byte BITS_SINGLE_BLOCK = 5;

    // ---------------------------------------------------------------------
    // Raster helpers
    // ---------------------------------------------------------------------

    private static WritableRaster createRgbaRaster(int width, int height) {
        return Raster.createInterleavedRaster(DataBuffer.TYPE_BYTE, width, height, 4, null);
    }

    private static void setPixel(WritableRaster raster, int x, int y, int r, int g, int b, int a) {
        raster.setDataElements(x, y, new byte[] {(byte) r, (byte) g, (byte) b, (byte) a});
    }

    private static int[] getPixel(Raster raster, int x, int y) {
        byte[] elements = new byte[4];
        raster.getDataElements(x, y, elements);

        return new int[] {elements[0] & 0xff, elements[1] & 0xff, elements[2] & 0xff, elements[3] & 0xff};
    }

    private static void assertPixel(Raster raster, int x, int y, int r, int g, int b, int a) {
        assertArrayEquals(new int[] {r, g, b, a}, getPixel(raster, x, y),
                "Pixel (" + x + ", " + y + ")");
    }

    /**
     * Creates a predictor transform image data raster (the "predictor modes" image) of the
     * given size, where the green band (band index 1) holds the predictor mode for each block.
     * The other bands hold decoy values, as only band 1 may be consulted.
     */
    private static WritableRaster createModeData(int width, int height, int... modes) {
        assertEquals(width * height, modes.length, "One mode per block required");

        WritableRaster data = Raster.createInterleavedRaster(DataBuffer.TYPE_BYTE, width, height, 4, null);

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int mode = modes[y * width + x];
                data.setSample(x, y, 0, 0xff - mode);    // Decoy, must be ignored
                data.setSample(x, y, 1, mode);          // The predictor mode
                data.setSample(x, y, 2, 0xff - mode);   // Decoy, must be ignored
                data.setSample(x, y, 3, 0xff - mode);   // Decoy, must be ignored
            }
        }

        return data;
    }

    /** Applies the inverse predictor using a single block covering the entire image. */
    private static void applyInverse(WritableRaster image, int mode) {
        new PredictorTransform(createModeData(1, 1, mode), BITS_SINGLE_BLOCK).applyInverse(image);
    }

    /**
     * Creates a 3x3 image, where the left border and the top border, once reconstructed, becomes:
     * <pre>
     *  (0,0) = (10, 10, 10,   9)
     *  (1,0) = (30, 30, 30,  29)
     *  (2,0) = (60, 60, 60,  59)
     *  (0,1) = (50, 50, 50,  49)
     *  (0,2) = (120,120,120, 119)
     * </pre>
     * The pixel under test is (1,1) with raw value (100, 110, 120, 130).
     */
    private static WritableRaster createStandardGrid() {
        WritableRaster raster = createRgbaRaster(3, 3);

        setPixel(raster, 0, 0, 10, 10, 10, 10);
        setPixel(raster, 1, 0, 20, 20, 20, 20);
        setPixel(raster, 2, 0, 30, 30, 30, 30);
        setPixel(raster, 0, 1, 40, 40, 40, 40);
        setPixel(raster, 1, 1, 100, 110, 120, 130);
        setPixel(raster, 2, 1, 60, 60, 60, 60);
        setPixel(raster, 0, 2, 70, 70, 70, 70);
        setPixel(raster, 1, 2, 80, 80, 80, 80);
        setPixel(raster, 2, 2, 90, 90, 90, 90);

        return raster;
    }

    private static void assertStandardGridInteriorPixel(int mode, int r, int g, int b, int a) {
        WritableRaster raster = createStandardGrid();
        applyInverse(raster, mode);

        // Sanity check: borders are reconstructed independent of the predictor mode
        assertPixel(raster, 0, 0, 10, 10, 10, 9);
        assertPixel(raster, 1, 0, 30, 30, 30, 29);
        assertPixel(raster, 2, 0, 60, 60, 60, 59);
        assertPixel(raster, 0, 1, 50, 50, 50, 49);
        assertPixel(raster, 0, 2, 120, 120, 120, 119);

        assertPixel(raster, 1, 1, r, g, b, a);
    }

    // ---------------------------------------------------------------------
    // Border handling
    // ---------------------------------------------------------------------

    @Test
    @DisplayName("Single pixel image: top-left pixel is predicted black (alpha + 0xff)")
    void testSinglePixelBlackPrediction() {
        WritableRaster raster = createRgbaRaster(1, 1);
        setPixel(raster, 0, 0, 10, 20, 30, 40);

        applyInverse(raster, PredictorMode.BLACK);

        assertPixel(raster, 0, 0, 10, 20, 30, 39);
    }

    @Test
    @DisplayName("Top-left pixel with zero alpha becomes fully opaque")
    void testSinglePixelZeroAlpha() {
        WritableRaster raster = createRgbaRaster(1, 1);
        setPixel(raster, 0, 0, 10, 20, 30, 0);

        applyInverse(raster, PredictorMode.BLACK);

        assertPixel(raster, 0, 0, 10, 20, 30, 255);
    }

    @Test
    @DisplayName("Top-left pixel is predicted black for every predictor mode")
    void testTopLeftPixelIgnoresPredictorMode() {
        for (int mode = PredictorMode.BLACK; mode <= PredictorMode.CLAMP_ADD_SUB_HALF; mode++) {
            WritableRaster raster = createRgbaRaster(1, 1);
            setPixel(raster, 0, 0, 1, 2, 3, 4);

            applyInverse(raster, mode);

            assertPixel(raster, 0, 0, 1, 2, 3, 3);
        }
    }

    @Test
    @DisplayName("Single row image: all pixels after the first are predicted from the left neighbour")
    void testSingleRowUsesLeftPredictor() {
        WritableRaster raster = createRgbaRaster(3, 1);
        setPixel(raster, 0, 0, 1, 2, 3, 4);
        setPixel(raster, 1, 0, 5, 6, 7, 8);
        setPixel(raster, 2, 0, 9, 10, 11, 12);

        applyInverse(raster, PredictorMode.BLACK);

        assertPixel(raster, 0, 0, 1, 2, 3, 3);
        assertPixel(raster, 1, 0, 6, 8, 10, 11);
        assertPixel(raster, 2, 0, 15, 18, 21, 23);
    }

    @Test
    @DisplayName("Single column image: all pixels after the first are predicted from the top neighbour")
    void testSingleColumnUsesTopPredictor() {
        WritableRaster raster = createRgbaRaster(1, 3);
        setPixel(raster, 0, 0, 1, 2, 3, 4);
        setPixel(raster, 0, 1, 5, 6, 7, 8);
        setPixel(raster, 0, 2, 9, 10, 11, 12);

        applyInverse(raster, PredictorMode.BLACK);

        assertPixel(raster, 0, 0, 1, 2, 3, 3);
        assertPixel(raster, 0, 1, 6, 8, 10, 11);
        assertPixel(raster, 0, 2, 15, 18, 21, 23);
    }

    @Test
    @DisplayName("Top row and left column ignore the predictor mode and use L and T respectively")
    void testBorderPixelsIgnorePredictorMode() {
        WritableRaster raster = createRgbaRaster(2, 2);
        setPixel(raster, 0, 0, 1, 2, 3, 4);
        setPixel(raster, 1, 0, 5, 6, 7, 8);
        setPixel(raster, 0, 1, 9, 10, 11, 12);
        setPixel(raster, 1, 1, 13, 14, 15, 16);

        // BLACK would leave the interior alpha untouched except for the black prediction
        applyInverse(raster, PredictorMode.BLACK);

        assertPixel(raster, 0, 0, 1, 2, 3, 3);
        // (1, 0) uses L, not BLACK
        assertPixel(raster, 1, 0, 6, 8, 10, 11);
        // (0, 1) uses T, not BLACK
        assertPixel(raster, 0, 1, 10, 12, 14, 15);
        // (1, 1) uses BLACK, ie. only the alpha is modified
        assertPixel(raster, 1, 1, 13, 14, 15, 15);
    }

    // ---------------------------------------------------------------------
    // Predictor modes, interior pixels
    // ---------------------------------------------------------------------

    @Test
    @DisplayName("BLACK predictor adds black (0x000000ff) to the pixel")
    void testModeBlack() {
        assertStandardGridInteriorPixel(PredictorMode.BLACK, 100, 110, 120, 129);
    }

    @Test
    @DisplayName("L predictor adds the left pixel")
    void testModeLeft() {
        assertStandardGridInteriorPixel(PredictorMode.L, 150, 160, 170, 179);
    }

    @Test
    @DisplayName("T predictor adds the top pixel")
    void testModeTop() {
        assertStandardGridInteriorPixel(PredictorMode.T, 130, 140, 150, 159);
    }

    @Test
    @DisplayName("TR predictor adds the top right pixel")
    void testModeTopRight() {
        assertStandardGridInteriorPixel(PredictorMode.TR, 160, 170, 180, 189);
    }

    @Test
    @DisplayName("TL predictor adds the top left pixel")
    void testModeTopLeft() {
        assertStandardGridInteriorPixel(PredictorMode.TL, 110, 120, 130, 139);
    }

    @Test
    @DisplayName("AVG_L_TR_T predictor adds Average2(Average2(L, TR), T)")
    void testModeAverageLeftTopRightTop() {
        assertStandardGridInteriorPixel(PredictorMode.AVG_L_TR_T, 142, 152, 162, 171);
    }

    @Test
    @DisplayName("AVG_L_TL predictor adds Average2(L, TL)")
    void testModeAverageLeftTopLeft() {
        assertStandardGridInteriorPixel(PredictorMode.AVG_L_TL, 130, 140, 150, 159);
    }

    @Test
    @DisplayName("AVG_L_T predictor adds Average2(L, T)")
    void testModeAverageLeftTop() {
        assertStandardGridInteriorPixel(PredictorMode.AVG_L_T, 140, 150, 160, 169);
    }

    @Test
    @DisplayName("AVG_TL_T predictor adds Average2(TL, T)")
    void testModeAverageTopLeftTop() {
        assertStandardGridInteriorPixel(PredictorMode.AVG_TL_T, 120, 130, 140, 149);
    }

    @Test
    @DisplayName("AVG_T_TR predictor adds Average2(T, TR)")
    void testModeAverageTopTopRight() {
        assertStandardGridInteriorPixel(PredictorMode.AVG_T_TR, 145, 155, 165, 174);
    }

    @Test
    @DisplayName("AVG_L_TL_T_TR predictor adds Average2(Average2(L, TL), Average2(T, TR))")
    void testModeAverageAll() {
        assertStandardGridInteriorPixel(PredictorMode.AVG_L_TL_T_TR, 137, 147, 157, 166);
    }

    @Test
    @DisplayName("SELECT predictor adds the left pixel when it is closer to the estimate")
    void testModeSelectPicksLeft() {
        assertStandardGridInteriorPixel(PredictorMode.SELECT, 150, 160, 170, 179);
    }

    @Test
    @DisplayName("SELECT predictor adds the top pixel when it is closer to the estimate")
    void testModeSelectPicksTop() {
        WritableRaster raster = createRgbaRaster(3, 3);
        setPixel(raster, 0, 0, 0, 0, 0, 1);        // TL reconstructs to (0, 0, 0, 0)
        setPixel(raster, 1, 0, 50, 50, 50, 50);    // T  reconstructs to (50, 50, 50, 50)
        setPixel(raster, 0, 1, 10, 10, 10, 10);    // L  reconstructs to (10, 10, 10, 10)
        setPixel(raster, 1, 1, 0, 0, 0, 0);

        applyInverse(raster, PredictorMode.SELECT);

        // Estimate is (60, 60, 60, 60); distance to T (40) is smaller than to L (200)
        assertPixel(raster, 1, 1, 50, 50, 50, 50);
    }

    @Test
    @DisplayName("SELECT predictor prefers the top pixel on a tie")
    void testModeSelectTieGoesToTop() {
        WritableRaster raster = createRgbaRaster(3, 3);
        setPixel(raster, 0, 0, 0, 0, 0, 1);        // TL reconstructs to (0, 0, 0, 0)
        setPixel(raster, 1, 0, 40, 30, 20, 10);    // T
        setPixel(raster, 0, 1, 10, 20, 30, 40);    // L
        setPixel(raster, 1, 1, 0, 0, 0, 0);

        applyInverse(raster, PredictorMode.SELECT);

        // Estimate is (50, 50, 50, 50); both Manhattan distances are 100
        assertPixel(raster, 1, 1, 40, 30, 20, 10);
    }

    @Test
    @DisplayName("CLAMP_ADD_SUB_FULL predictor adds Clamp(L + T - TL)")
    void testModeClampAddSubtractFull() {
        assertStandardGridInteriorPixel(PredictorMode.CLAMP_ADD_SUB_FULL, 170, 180, 190, 199);
    }

    @Test
    @DisplayName("CLAMP_ADD_SUB_FULL predictor clamps values above 255")
    void testModeClampAddSubtractFullClampsHigh() {
        WritableRaster raster = createRgbaRaster(3, 3);
        setPixel(raster, 0, 0, 0, 0, 0, 1);            // TL reconstructs to (0, 0, 0, 0)
        setPixel(raster, 1, 0, 200, 200, 200, 200);    // T
        setPixel(raster, 0, 1, 200, 200, 200, 200);    // L
        setPixel(raster, 1, 1, 0, 0, 0, 0);

        applyInverse(raster, PredictorMode.CLAMP_ADD_SUB_FULL);

        // 200 + 200 - 0 = 400, clamped to 255
        assertPixel(raster, 1, 1, 255, 255, 255, 255);
    }

    @Test
    @DisplayName("CLAMP_ADD_SUB_FULL predictor clamps values below 0")
    void testModeClampAddSubtractFullClampsLow() {
        WritableRaster raster = createRgbaRaster(3, 3);
        setPixel(raster, 0, 0, 250, 250, 250, 251);    // TL reconstructs to (250, 250, 250, 250)
        setPixel(raster, 1, 0, 6, 6, 6, 6);            // T reconstructs to (0, 0, 0, 0)
        setPixel(raster, 0, 1, 6, 6, 6, 6);            // L reconstructs to (0, 0, 0, 0)
        setPixel(raster, 1, 1, 5, 6, 7, 8);

        applyInverse(raster, PredictorMode.CLAMP_ADD_SUB_FULL);

        // 0 + 0 - 250 = -250, clamped to 0
        assertPixel(raster, 1, 1, 5, 6, 7, 8);
    }

    @Test
    @DisplayName("CLAMP_ADD_SUB_HALF predictor adds Clamp(Average2(L, T) + (Average2(L, T) - TL) / 2)")
    void testModeClampAddSubtractHalf() {
        assertStandardGridInteriorPixel(PredictorMode.CLAMP_ADD_SUB_HALF, 155, 165, 175, 184);
    }

    @Test
    @DisplayName("CLAMP_ADD_SUB_HALF predictor clamps values above 255")
    void testModeClampAddSubtractHalfClampsHigh() {
        WritableRaster raster = createRgbaRaster(3, 3);
        setPixel(raster, 0, 0, 0, 0, 0, 1);            // TL reconstructs to (0, 0, 0, 0)
        setPixel(raster, 1, 0, 255, 255, 255, 255);    // T
        setPixel(raster, 0, 1, 255, 255, 255, 255);    // L
        setPixel(raster, 1, 1, 0, 0, 0, 0);

        applyInverse(raster, PredictorMode.CLAMP_ADD_SUB_HALF);

        // Average2(255, 255) + (255 - 0) / 2 = 382, clamped to 255
        assertPixel(raster, 1, 1, 255, 255, 255, 255);
    }

    @Test
    @DisplayName("CLAMP_ADD_SUB_HALF predictor clamps values below 0")
    void testModeClampAddSubtractHalfClampsLow() {
        WritableRaster raster = createRgbaRaster(3, 3);
        setPixel(raster, 0, 0, 250, 250, 250, 251);    // TL reconstructs to (250, 250, 250, 250)
        setPixel(raster, 1, 0, 6, 6, 6, 6);            // T reconstructs to (0, 0, 0, 0)
        setPixel(raster, 0, 1, 6, 6, 6, 6);            // L reconstructs to (0, 0, 0, 0)
        setPixel(raster, 1, 1, 5, 6, 7, 8);

        applyInverse(raster, PredictorMode.CLAMP_ADD_SUB_HALF);

        // Average2(0, 0) + (0 - 250) / 2 = -125, clamped to 0
        assertPixel(raster, 1, 1, 5, 6, 7, 8);
    }

    @Test
    @DisplayName("CLAMP_ADD_SUB_HALF predictor truncates the halved difference towards zero")
    void testModeClampAddSubtractHalfTruncatesTowardsZero() {
        WritableRaster raster = createRgbaRaster(3, 3);
        setPixel(raster, 0, 0, 15, 15, 15, 16);        // TL reconstructs to (15, 15, 15, 15)
        setPixel(raster, 1, 0, 251, 251, 251, 251);    // T reconstructs to (10, 10, 10, 10)
        setPixel(raster, 0, 1, 251, 251, 251, 251);    // L reconstructs to (10, 10, 10, 10)
        setPixel(raster, 1, 1, 0, 0, 0, 0);

        applyInverse(raster, PredictorMode.CLAMP_ADD_SUB_HALF);

        // 10 + (10 - 15) / 2 = 10 + (-2) = 8 (floor rounding would give 7)
        assertPixel(raster, 1, 1, 8, 8, 8, 8);
    }

    @Test
    @DisplayName("Average predictors round fractional averages down")
    void testAverageRoundsDown() {
        WritableRaster raster = createRgbaRaster(3, 3);
        setPixel(raster, 0, 0, 0, 0, 0, 1);            // TL reconstructs to (0, 0, 0, 0)
        setPixel(raster, 1, 0, 3, 5, 7, 9);            // T
        setPixel(raster, 0, 1, 4, 8, 10, 12);          // L
        setPixel(raster, 1, 1, 0, 0, 0, 0);

        applyInverse(raster, PredictorMode.AVG_L_T);

        // Average2((4, 8, 10, 12), (3, 5, 7, 9)) = (3, 6, 8, 10)
        assertPixel(raster, 1, 1, 3, 6, 8, 10);
    }

    @Test
    @DisplayName("Unknown predictor modes leave the pixel value unchanged")
    void testUnknownPredictorModeLeavesPixelUnchanged() {
        for (int mode : new int[] {14, 15}) {
            WritableRaster raster = createStandardGrid();
            applyInverse(raster, mode);

            assertPixel(raster, 1, 1, 100, 110, 120, 130);
            assertPixel(raster, 2, 1, 60, 60, 60, 60);
            assertPixel(raster, 1, 2, 80, 80, 80, 80);
            assertPixel(raster, 2, 2, 90, 90, 90, 90);
        }
    }

    @Test
    @DisplayName("TR predictor uses the leftmost pixel of the same row for the rightmost pixel")
    void testTopRightAtRightmostColumnWrapsToFirstPixelOfRow() {
        WritableRaster raster = createStandardGrid();
        applyInverse(raster, PredictorMode.TR);

        assertPixel(raster, 1, 1, 160, 170, 180, 189);
        // (2, 1) is the last pixel of its row, TR is then (0, 1) = (50, 50, 50, 49)
        assertPixel(raster, 2, 1, 110, 110, 110, 109);
        // (1, 2) uses the reconstructed (2, 1) as TR
        assertPixel(raster, 1, 2, 190, 190, 190, 189);
        // (2, 2) is the last pixel of its row, TR is then (0, 2) = (120, 120, 120, 119)
        assertPixel(raster, 2, 2, 210, 210, 210, 209);
    }

    @Test
    @DisplayName("AVG_L_TR_T predictor uses the leftmost pixel of the same row for the rightmost pixel")
    void testAverageLeftTopRightTopAtRightmostColumnWrapsToFirstPixelOfRow() {
        WritableRaster raster = createStandardGrid();
        applyInverse(raster, PredictorMode.AVG_L_TR_T);

        assertPixel(raster, 1, 1, 142, 152, 162, 171);
        // Predictor for (2, 1): Average2(Average2((142, 152, 162, 171), (50, 50, 50, 49)), (60, 60, 60, 59))
        //                       = Average2((96, 101, 106, 110), (60, 60, 60, 59)) = (78, 80, 83, 84)
        assertPixel(raster, 2, 1, 138, 140, 143, 144);
    }

    // ---------------------------------------------------------------------
    // Block indexing (x >> bits, y >> bits) and band selection
    // ---------------------------------------------------------------------

    @Test
    @DisplayName("Predictor mode is looked up per block, using the transform image bit depth")
    void testPredictorModeIsSelectedPerBlock() {
        WritableRaster raster = createRgbaRaster(4, 4);

        setPixel(raster, 0, 0, 10, 10, 10, 10);    // reconstructs to (10, 10, 10, 9)
        setPixel(raster, 1, 0, 20, 20, 20, 20);    // reconstructs to (30, 30, 30, 29)
        setPixel(raster, 2, 0, 30, 30, 30, 30);    // reconstructs to (60, 60, 60, 59)
        setPixel(raster, 3, 0, 40, 40, 40, 40);    // reconstructs to (100, 100, 100, 99)
        setPixel(raster, 0, 1, 50, 50, 50, 50);    // reconstructs to (60, 60, 60, 59)
        setPixel(raster, 0, 2, 60, 60, 60, 60);    // reconstructs to (120, 120, 120, 119)
        setPixel(raster, 0, 3, 60, 60, 60, 60);    // reconstructs to (180, 180, 180, 179)

        for (int y = 1; y < 4; y++) {
            for (int x = 1; x < 4; x++) {
                setPixel(raster, x, y, 0, 0, 0, 0);
            }
        }

        // 2x2 blocks of 2x2 pixels each
        WritableRaster modes = createModeData(2, 2,
                PredictorMode.T,        // block (0, 0)
                PredictorMode.BLACK,    // block (1, 0)
                PredictorMode.L,        // block (0, 1)
                PredictorMode.TR);      // block (1, 1)

        new PredictorTransform(modes, (byte) 1).applyInverse(raster);

        assertPixel(raster, 1, 1, 30, 30, 30, 29);     // T
        assertPixel(raster, 2, 1, 0, 0, 0, 255);       // BLACK
        assertPixel(raster, 3, 1, 0, 0, 0, 255);       // BLACK
        assertPixel(raster, 1, 2, 120, 120, 120, 119); // L
        assertPixel(raster, 1, 3, 180, 180, 180, 179); // L
        assertPixel(raster, 2, 2, 0, 0, 0, 255);       // TR of (3, 1)
        assertPixel(raster, 3, 2, 120, 120, 120, 119); // TR wraps to (0, 2)
        assertPixel(raster, 2, 3, 120, 120, 120, 119); // TR of (3, 2)
        assertPixel(raster, 3, 3, 180, 180, 180, 179); // TR wraps to (0, 3)
    }

    @Test
    @DisplayName("Predictor mode is read from the green band of the transform image")
    void testPredictorModeReadFromBandOne() {
        WritableRaster raster = createRgbaRaster(2, 2);
        setPixel(raster, 0, 0, 1, 2, 3, 4);
        setPixel(raster, 1, 0, 5, 6, 7, 8);
        setPixel(raster, 0, 1, 9, 10, 11, 12);
        setPixel(raster, 1, 1, 20, 21, 22, 23);

        // Band 0 says T, band 1 says L
        new PredictorTransform(createModeData(1, 1, PredictorMode.L), BITS_SINGLE_BLOCK).applyInverse(raster);

        // L prediction adds the reconstructed left pixel (10, 12, 14, 15)
        assertPixel(raster, 1, 1, 30, 33, 36, 38);
    }

    // ---------------------------------------------------------------------
    // Unsigned byte arithmetic
    // ---------------------------------------------------------------------

    @Test
    @DisplayName("Pixels are added using unsigned byte arithmetic, wrapping at 256")
    void testAdditionWrapsAt256() {
        WritableRaster raster = createRgbaRaster(1, 2);
        setPixel(raster, 0, 0, 200, 200, 200, 200);
        setPixel(raster, 0, 1, 200, 200, 200, 200);

        applyInverse(raster, PredictorMode.T);

        assertPixel(raster, 0, 0, 200, 200, 200, 199);
        // 200 + 200 = 400 -> 144, 200 + 199 = 399 -> 143
        assertPixel(raster, 0, 1, 144, 144, 144, 143);
    }
}

