    @Test
    void sharpnessFourAllowsInteriorDifferenceAtLimit() {
        MacroBlock cmb = newMacroBlock(40);
        MacroBlock lmb = newMacroBlock(40);

        fillPlane(cmb, Plane.U, flat(50));
        fillPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
        fillPlane(lmb, Plane.U, flat(10));
        fillPlane(lmb, Plane.V, flat(CHROMA_NEUTRAL));

        int[][] edge = rowPattern(39, 34, 33, 30);
        fillSubBlock(lmb, Plane.U, 1, 0, edge);
        fillSubBlock(lmb, Plane.U, 1, 1, edge);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 4, 0);

        // sharpness 4 halves the initial level and caps the interior limit at 9 - 4 = 5.
        // The interior difference of five is accepted at the cap, so filtering happens.
        assertPixels(rowPattern(45, 50, 50, 50), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(rowPattern(45, 50, 50, 50), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(rowPattern(39, 34, 33, 35), lmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(rowPattern(39, 34, 33, 35), lmb.getSubBlock(Plane.U, 1, 1));
    }

    @Test
    void sharpnessFiveRejectsInteriorDifferenceAboveLimit() {
        MacroBlock cmb = newMacroBlock(40);
        MacroBlock lmb = newMacroBlock(40);

        fillPlane(cmb, Plane.U, flat(50));
        fillPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
        fillPlane(lmb, Plane.U, flat(10));
        fillPlane(lmb, Plane.V, flat(CHROMA_NEUTRAL));

        int[][] edge = rowPattern(39, 34, 33, 30);
        fillSubBlock(lmb, Plane.U, 1, 0, edge);
        fillSubBlock(lmb, Plane.U, 1, 1, edge);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 5, 0);

        // sharpness 5 shifts by two and caps the interior limit at 9 - 5 = 4.
        // The interior difference of five now disables filtering entirely.
        assertPixels(flat(50), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(flat(50), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(edge, lmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(edge, lmb.getSubBlock(Plane.U, 1, 1));
    }

    @Test
    void skippedInnerLoopFilterLeavesInnerEdgesUntouched() throws Exception {
        MacroBlock cmb = newMacroBlock(20);

        fillPlane(cmb, Plane.U, flat(30));
