        Field skip = MacroBlock.class.getDeclaredField("skipInnerLoopFilter");
        skip.setAccessible(true);
        skip.setBoolean(cmb, true);

        LoopFilter.loopFilterUVBlock(cmb, null, null, 0, 1);

        assertPixels(flat(10), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(flat(10), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(flat(30), cmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(flat(30), cmb.getSubBlock(Plane.U, 1, 1));
        assertPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
    }

