    private static MacroBlock newMacroBlock(int filterLevel) {
        MacroBlock macroBlock = new MacroBlock(0, 0, false);
        macroBlock.setFilterLevel(filterLevel);
        return macroBlock;
    }

    private static void fillPlane(MacroBlock macroBlock, Plane plane, int[][] pattern) {
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                fillSubBlock(macroBlock, plane, i, j, pattern);
            }
        }
    }

    private static void fillSubBlock(MacroBlock macroBlock, Plane plane, int i, int j, int[][] pattern) {
        int[][] copy = new int[4][4];
        for (int x = 0; x < 4; x++) {
            System.arraycopy(pattern[x], 0, copy[x], 0, 4);
        }
        macroBlock.getSubBlock(plane, i, j).setDest(copy);
    }

    private static int[][] flat(int value) {
        int[][] dest = new int[4][4];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                dest[x][y] = value;
            }
        }
        return dest;
    }

    /**
     * Creates a plane whose value depends only on {@code x}; every row is identical.
     */
    private static int[][] rowPattern(int x0, int x1, int x2, int x3) {
        int[] values = {x0, x1, x2, x3};
        int[][] dest = new int[4][4];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                dest[x][y] = values[x];
            }
        }
        return dest;
    }

    /**
     * Creates a plane whose value depends only on {@code y}; every column is identical.
     */
    private static int[][] columnPattern(int y0, int y1, int y2, int y3) {
        int[] values = {y0, y1, y2, y3};
        int[][] dest = new int[4][4];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                dest[x][y] = values[y];
            }
        }
        return dest;
    }

    private static void assertPlane(MacroBlock macroBlock, Plane plane, int[][] expected) {
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                assertPixels(expected, macroBlock.getSubBlock(plane, i, j));
            }
        }
    }

    private static void assertPixels(int[][] expected, SubBlock subBlock) {
        int[][] actual = subBlock.getDest();
        assertNotNull(actual, "sub-block destination pixels should not be null");
        for (int x = 0; x < 4; x++) {
            assertArrayEquals(expected[x], actual[x], "unexpected pixel values in column x=" + x);
        }
    }
