    void hPredictionRepeatsLeftRowAcrossEachBlock() throws Exception {
        MacroBlock target = new MacroBlock(2, 1, true); // x = 1, y = 0
        target.setUvMode(Globals.H_PRED);

        MacroBlock left = new MacroBlock(1, 1, true);
        setRecon(left.getUSubBlock(1, 0), withRow3(5, 6, 7, 8));
        setRecon(left.getUSubBlock(1, 1), withRow3(50, 60, 70, 80));
        setRecon(left.getVSubBlock(1, 0), withRow3(105, 106, 107, 108));
        setRecon(left.getVSubBlock(1, 1), withRow3(150, 160, 170, 180));

        VP8Frame frame = frameWithNeighbours(target, null, left, null);

        target.predictUV(frame);

        int[][] expectedU0 = columnsFromRow(5, 6, 7, 8);
        int[][] expectedU1 = columnsFromRow(50, 60, 70, 80);
        int[][] expectedV0 = columnsFromRow(105, 106, 107, 108);
        int[][] expectedV1 = columnsFromRow(150, 160, 170, 180);

        for (int x = 0; x < 2; x++) {
            assertMatrixEquals(expectedU0, target.getUSubBlock(x, 0).getPredict(), "U[" + x + "][0]");
            assertMatrixEquals(expectedU1, target.getUSubBlock(x, 1).getPredict(), "U[" + x + "][1]");
            assertMatrixEquals(expectedV0, target.getVSubBlock(x, 0).getPredict(), "V[" + x + "][0]");
            assertMatrixEquals(expectedV1, target.getVSubBlock(x, 1).getPredict(), "V[" + x + "][1]");
        }
    }

    // --- TM_PRED -----------------------------------------------------------

    @Test
    void tmPredictionCombinesLeftAboveAndAboveLeftSamples() throws Exception {
        MacroBlock target = new MacroBlock(2, 2, true); // x = 1, y = 1
        target.setUvMode(Globals.TM_PRED);

        MacroBlock above = new MacroBlock(1, 1, true);
        setRecon(above.getUSubBlock(0, 1), constantMatrix(30));
        setRecon(above.getUSubBlock(1, 1), constantMatrix(40));
        setRecon(above.getVSubBlock(0, 1), constantMatrix(60));
        setRecon(above.getVSubBlock(1, 1), constantMatrix(70));

        MacroBlock left = new MacroBlock(1, 1, true);
        setRecon(left.getUSubBlock(1, 0), constantMatrix(10));
        setRecon(left.getUSubBlock(1, 1), constantMatrix(20));
        setRecon(left.getVSubBlock(1, 0), constantMatrix(15));
        setRecon(left.getVSubBlock(1, 1), constantMatrix(25));

        MacroBlock aboveLeft = new MacroBlock(1, 1, true);
        setRecon(aboveLeft.getUSubBlock(1, 1), constantMatrix(5));
        setRecon(aboveLeft.getVSubBlock(1, 1), constantMatrix(5));

        VP8Frame frame = frameWithNeighbours(target, above, left, aboveLeft);

        target.predictUV(frame);

        // U: left[b] + above[d] - aboveLeft
        assertAllPixels(target.getUSubBlock(0, 0).getDest(), 10 + 30 - 5, "U[0][0]");
        assertAllPixels(target.getUSubBlock(1, 0).getDest(), 10 + 40 - 5, "U[1][0]");
        assertAllPixels(target.getUSubBlock(0, 1).getDest(), 20 + 30 - 5, "U[0][1]");
        assertAllPixels(target.getUSubBlock(1, 1).getDest(), 20 + 40 - 5, "U[1][1]");

        // V: left[b] + above[d] - aboveLeft
        assertAllPixels(target.getVSubBlock(0, 0).getDest(), 15 + 60 - 5, "V[0][0]");
        assertAllPixels(target.getVSubBlock(1, 0).getDest(), 15 + 70 - 5, "V[1][0]");
        assertAllPixels(target.getVSubBlock(0, 1).getDest(), 25 + 60 - 5, "V[0][1]");
        assertAllPixels(target.getVSubBlock(1, 1).getDest(), 25 + 70 - 5, "V[1][1]");
    }

    @Test
    void tmPredictionClampsOutOfRangePixels() throws Exception {
        MacroBlock target = new MacroBlock(2, 2, true); // x = 1, y = 1
        target.setUvMode(Globals.TM_PRED);

        MacroBlock above = new MacroBlock(1, 1, true);
        setRecon(above.getUSubBlock(0, 1), constantMatrix(200));
        setRecon(above.getUSubBlock(1, 1), constantMatrix(0));
        setRecon(above.getVSubBlock(0, 1), constantMatrix(200));
        setRecon(above.getVSubBlock(1, 1), constantMatrix(0));

        MacroBlock left = new MacroBlock(1, 1, true);
        setRecon(left.getUSubBlock(1, 0), constantMatrix(200));
        setRecon(left.getUSubBlock(1, 1), constantMatrix(0));
        setRecon(left.getVSubBlock(1, 0), constantMatrix(200));
        setRecon(left.getVSubBlock(1, 1), constantMatrix(0));

        MacroBlock aboveLeft = new MacroBlock(1, 1, true);
        setRecon(aboveLeft.getUSubBlock(1, 1), constantMatrix(100));
        setRecon(aboveLeft.getVSubBlock(1, 1), constantMatrix(100));

        VP8Frame frame = frameWithNeighbours(target, above, left, aboveLeft);

        target.predictUV(frame);

        // 200 + 200 - 100 = 300 clamps to 255
        assertAllPixels(target.getUSubBlock(0, 0).getDest(), 255, "U[0][0] clamped high");
        // 200 + 0 - 100 = 100
        assertAllPixels(target.getUSubBlock(1, 0).getDest(), 100, "U[1][0] in range");
        // 0 + 200 - 100 = 100
        assertAllPixels(target.getUSubBlock(0, 1).getDest(), 100, "U[0][1] in range");
        // 0 + 0 - 100 = -100 clamps to 0
        assertAllPixels(target.getUSubBlock(1, 1).getDest(), 0, "U[1][1] clamped low");

        assertAllPixels(target.getVSubBlock(0, 0).getDest(), 255, "V[0][0] clamped high");
        assertAllPixels(target.getVSubBlock(1, 0).getDest(), 100, "V[1][0] in range");
        assertAllPixels(target.getVSubBlock(0, 1).getDest(), 100, "V[0][1] in range");
        assertAllPixels(target.getVSubBlock(1, 1).getDest(), 0, "V[1][1] clamped low");
    }

    // --- Invalid mode ------------------------------------------------------

    @Test
    void unknownUvModeThrowsAssertionError() throws Exception {
        MacroBlock target = new MacroBlock(2, 2, true);
        target.setUvMode(99);
        target.setYMode(7);

        MacroBlock above = new MacroBlock(1, 1, true);
        MacroBlock left = new MacroBlock(1, 1, true);
        VP8Frame frame = frameWithNeighbours(target, above, left, null);

        AssertionError error = assertThrows(AssertionError.class, () -> target.predictUV(frame));
        assertTrue(error.getMessage().contains("TODO predict_mb_uv"), "Unexpected message: " + error.getMessage());
        assertTrue(error.getMessage().contains("7"), "Message should mention the Y mode: " + error.getMessage());
    }

    // --- Helpers -----------------------------------------------------------

    private static VP8Frame frameWithNeighbours(MacroBlock target, MacroBlock above,
                                                MacroBlock left, MacroBlock aboveLeft) throws Exception {
        int tx = target.getX();
        int ty = target.getY();
        int size = Math.max(tx + 2, 2);

        MacroBlock filler = new MacroBlock(1, 1, false);
        MacroBlock[] currentRow = new MacroBlock[size];
        MacroBlock[] previousRow = new MacroBlock[size];
        MacroBlock[] topRow = new MacroBlock[size];
        Arrays.fill(currentRow, filler);
        Arrays.fill(previousRow, filler);
        Arrays.fill(topRow, filler);

        // getMacroBlock(tx - 1, ty) returns currentRow[(tx - 1) + 1] == currentRow[tx]
        if (left != null) {
            currentRow[tx] = left;
        }
        // getMacroBlock(tx, ty - 1) returns previousRow[tx + 1]
        if (above != null) {
            previousRow[tx + 1] = above;
        }
        // getMacroBlock(tx - 1, ty - 1) returns previousRow[(tx - 1) + 1] == previousRow[tx]
        if (aboveLeft != null) {
            previousRow[tx] = aboveLeft;
        }

        VP8Frame frame = new VP8Frame(
                new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0])), false);

        setField(frame, "currentMacroBlockRowIndex", ty);
        setField(frame, "currentMacroBlockRow", currentRow);
        setField(frame, "previousMacroBlockRow", previousRow);
        setField(frame, "topMacroBlockRow", topRow);
        setField(frame, "macroBlockRows", ty + 10);
        setField(frame, "macroBlockCols", tx + 10);

        return frame;
    }

    private static void setField(VP8Frame frame, String name, Object value) throws Exception {
        Field field = VP8Frame.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(frame, value);
    }

    private static void setRecon(SubBlock subBlock, int[][] matrix) {
        subBlock.setDest(matrix);
    }

    private static int[][] constantMatrix(int value) {
        int[][] matrix = new int[4][4];
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                matrix[r][c] = value;
            }
        }
        return matrix;
    }

    private static int[][] withColumn3(int... values) {
        int[][] matrix = new int[4][4];
        for (int r = 0; r < 4; r++) {
            matrix[r][3] = values[r];
        }
        return matrix;
    }

    private static int[][] withRow3(int... values) {
        int[][] matrix = new int[4][4];
        for (int c = 0; c < 4; c++) {
            matrix[3][c] = values[c];
        }
        return matrix;
    }

    /** Each row is the given column vector, matching V_PRED's copy semantics. */
    private static int[][] rowsFromColumn(int... column) {
        int[][] matrix = new int[4][4];
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                matrix[r][c] = column[r];
            }
        }
        return matrix;
    }

    /** Each row equals the given row vector, matching H_PRED's copy semantics. */
    private static int[][] columnsFromRow(int... row) {
        int[][] matrix = new int[4][4];
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                matrix[r][c] = row[c];
            }
        }
        return matrix;
    }

    private static void assertAllSubBlocks(MacroBlock target, int expectedU, int expectedV, String message) {
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                assertAllPixels(target.getUSubBlock(i, j).getPredict(), expectedU, message + " U[" + i + "][" + j + "]");
                assertAllPixels(target.getVSubBlock(i, j).getPredict(), expectedV, message + " V[" + i + "][" + j + "]");
            }
        }
    }

    private static void assertAllSubBlocksConstant(MacroBlock target, int expected, String message) {
        assertAllSubBlocks(target, expected, expected, message);
    }

    private static void assertAllPixels(int[][] actual, int expected, String message) {
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                assertEquals(expected, actual[r][c], message + " at [" + r + "][" + c + "]");
            }
        }
    }

    private static void assertMatrixEquals(int[][] expected, int[][] actual, String message) {
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                assertEquals(expected[r][c], actual[r][c], message + " at [" + r + "][" + c + "]");
            }
        }
    }
