public void predictY(VP8Frame frame) {
        MacroBlock aboveMb = frame.getMacroBlock(x, y - 1);
        MacroBlock leftMb = frame.getMacroBlock(x - 1, y);

        switch (this.yMode) {
            case Globals.DC_PRED:
                // System.out.println("DC_PRED");
                boolean up_available = false;
                boolean left_available = false;

                int average = 0;
                int expected_dc;
                if (x > 0) {
                    left_available = true;
                }
                if (y > 0) {
                    up_available = true;
                }

                if (up_available || left_available) {
                    if (up_available) {
                        for (int j = 0; j < 4; j++) {
                            SubBlock sb = aboveMb.getYSubBlock(j, 3);
                            for (int i = 0; i < 4; i++) {
                                average += sb.getRecon()[i][3];
                            }
                        }
                    }

                    if (left_available) {
                        for (int j = 0; j < 4; j++) {
                            SubBlock sb = leftMb.getYSubBlock(3, j);
                            for (int i = 0; i < 4; i++) {
                                average += sb.getRecon()[3][i];
                            }
                        }
                    }

                    int shift = 3;
                    if (up_available) {
                        shift++;
                    }
                    if (left_available) {
                        shift++;
                    }

                    expected_dc = (average + (1 << (shift - 1))) >> shift;
                }
                else {
                    expected_dc = 128;
                }

                int[][] fill = new int[4][4];
                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        fill[x][y] = expected_dc;
                    }
                }
                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        SubBlock sb = ySubBlocks[x][y];
                        sb.setPredict(fill);
                    }
                }

                break;
            case Globals.V_PRED:
                // System.out.println("V_PRED");

                SubBlock[] aboveYSb = new SubBlock[4];
                for (int x = 0; x < 4; x++) {
                    aboveYSb[x] = aboveMb.getYSubBlock(x, 3);
                }

                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        SubBlock sb = ySubBlocks[x][y];
                        int[][] block = new int[4][4];
                        for (int j = 0; j < 4; j++) {
                            for (int i = 0; i < 4; i++) {
                                block[i][j] = aboveYSb[x].getReconPredict(
                                        Globals.B_VE_PRED, false)[i][3];
                            }
                        }
                        sb.setPredict(block);
                    }
                }

                break;

            case Globals.H_PRED:
                // System.out.println("H_PRED");

                SubBlock[] leftYSb = new SubBlock[4];
                for (int x = 0; x < 4; x++) {
                    leftYSb[x] = leftMb.getYSubBlock(3, x);
                }

                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        SubBlock sb = ySubBlocks[x][y];
                        int[][] block = new int[4][4];
                        for (int j = 0; j < 4; j++) {
                            for (int i = 0; i < 4; i++) {
                                block[i][j] = leftYSb[y].getReconPredict(
                                        Globals.B_DC_PRED, true)[3][j];
                            }
                        }
                        sb.setPredict(block);
                    }
                }

//                 SubBlock[] leftUSb = new SubBlock[2];
//                 for (int x = 0; x < 2; x++) {
//                     leftUSb[x] = leftMb.getYSubBlock(1, x);
//                 }

                break;
            case Globals.TM_PRED:
                // System.out.println("TM_PRED MB");
                boolean aboveRowAvailableY = this.y > 0;
                MacroBlock ALMb = frame.getMacroBlock(x - 1, y - 1);
                SubBlock ALSb = ALMb.getYSubBlock(3, 3);
                int al = ALSb.getReconAboveLeft(aboveRowAvailableY)[3][3];

                aboveYSb = new SubBlock[4];
                leftYSb = new SubBlock[4];
                for (int x = 0; x < 4; x++) {
                    aboveYSb[x] = aboveMb.getYSubBlock(x, 3);
                }
                for (int x = 0; x < 4; x++) {
                    leftYSb[x] = leftMb.getYSubBlock(3, x);
                }
//                 fill = new int[4][4];

                for (int b = 0; b < 4; b++) {
                    for (int a = 0; a < 4; a++) {

                        for (int d = 0; d < 4; d++) {
                            for (int c = 0; c < 4; c++) {
                                int pred = leftYSb[b].getReconLeft()[3][a]
                                        + aboveYSb[d].getReconAbove()[c][3] - al;

                                ySubBlocks[d][b].setPixel(c, a,
                                        Globals.clamp(pred, 255));
                            }
                        }
                    }
                }

                break;
            default:
                System.out.println("TODO predict_mb_y: " + this.yMode);
                System.exit(0);
        }
    }

