    private static void installMacroBlocks(VP8Frame frame, MacroBlock macroBlock,
                                           MacroBlock above, MacroBlock left,
                                           MacroBlock aboveLeft) throws Exception {
        int x = macroBlock.getX();
        int y = macroBlock.getY();
        int size = Math.max(4, x + 2);

        MacroBlock filler = newMacroBlock();
        MacroBlock[] currentRow = filledRow(size, filler);
        MacroBlock[] previousRow = filledRow(size, filler);
        MacroBlock[] topRow = filledRow(size, filler);

        currentRow[x + 1] = macroBlock;
        currentRow[x] = left != null ? left : filler;
        previousRow[x + 1] = above != null ? above : filler;
        previousRow[x] = aboveLeft != null ? aboveLeft : filler;

        setIntField(frame, "currentMacroBlockRowIndex", y);
        setField(frame, "currentMacroBlockRow", currentRow);
        setField(frame, "previousMacroBlockRow", previousRow);
        setField(frame, "topMacroBlockRow", topRow);
        setIntField(frame, "macroBlockCols", size - 2);
        setIntField(frame, "macroBlockRows", 4);
    }

    private static MacroBlock[] filledRow(int size, MacroBlock value) {
        MacroBlock[] row = new MacroBlock[size];
        for (int i = 0; i < size; i++) {
            row[i] = value;
        }
        return row;
    }

    private static void setLastColumn(SubBlock subBlock, int[] values) {
        int[][] recon = filledBlock(200);
        for (int y = 0; y < 4; y++) {
            recon[3][y] = values[y];
        }
        subBlock.setDest(recon);
    }

    private static void setBottomRow(SubBlock subBlock, int[] values) {
        int[][] recon = filledBlock(200);
        for (int x = 0; x < 4; x++) {
            recon[x][3] = values[x];
        }
        subBlock.setDest(recon);
    }

    private static void fillLastColumn(MacroBlock macroBlock, int value) {
        for (int column = 0; column < 4; column++) {
            setLastColumn(macroBlock.getYSubBlock(column, 3), new int[]{value, value, value, value});
        }
    }

    private static void fillBottomRow(MacroBlock macroBlock, int value) {
        for (int row = 0; row < 4; row++) {
            setBottomRow(macroBlock.getYSubBlock(3, row), new int[]{value, value, value, value});
        }
    }

    private static int[][] filledBlock(int value) {
        int[][] block = new int[4][4];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                block[x][y] = value;
            }
        }
        return block;
    }

    private static void assertUniformPredict(MacroBlock macroBlock, int expected) {
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                int[][] actual = macroBlock.getYSubBlock(x, y).getPredict();
                assertNotNull(actual);
                assertUniform(actual, expected, "prediction at target (" + x + ", " + y + ')');
            }
        }
    }

    private static void assertUniformDest(SubBlock subBlock, int expected) {
        assertUniform(subBlock.getDest(), expected, "destination");
    }

    private static void assertUniform(int[][] actual, int expected, String description) {
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                assertEquals(expected, actual[x][y], "Unexpected " + description
                        + " pixel (" + x + ", " + y + ')');
            }
        }
    }

    private static void assertDest(SubBlock subBlock, int[][] expected) {
        int[][] actual = subBlock.getDest();
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                assertEquals(expected[x][y], actual[x][y],
                        "Unexpected destination pixel (" + x + ", " + y + ')');
            }
        }
    }

    private static void setField(Object target, String name, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static void setIntField(Object target, String name, int value) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.setInt(target, value);
    }
