/**
     * Whether this sub block has been reconstructed.
     */
public boolean hasRecon() {
        return recon != null;
    }

/**
     * As {@link #getPredict(int, boolean)}, but returning the unfiltered
     * reconstruction. Use this when reading a *neighbouring* sub block as
     * prediction context.
     */
public int[][] getReconPredict(int intraBMode, boolean left) {
        if (recon != null) {
            return recon;
        }
        if (predict != null) {
            return predict;
        }

        return borderSamples(left && isLeftBorder129(intraBMode));
    }

public int getMode() {
        return mode;
    }

public Plane getPlane() {
        return plane;
    }

public void setPredict(int[][] predict) {
        this.predict = predict;
    }

SubBlock getAboveRightSubBlock(SubBlock sb, SubBlock.Plane plane) {
        // this might break at right edge
        SubBlock r;
        MacroBlock mb = sb.getMacroBlock();
        int x = mb.getSubblockX(sb);
        int y = mb.getSubblockY(sb);

        if (plane == SubBlock.Plane.Y1) {
            // top row
            if (y == 0 && x < 3) {
                MacroBlock mb2 = this.getMacroBlock(mb.getX(), mb.getY() - 1);
                r = mb2.getSubBlock(plane, x + 1, 3);
                return r;
            }
            //top right
            else if (y == 0 && x == 3) {
                MacroBlock mb2 = this.getMacroBlock(mb.getX() + 1, mb.getY() - 1);
                r = mb2.getSubBlock(plane, 0, 3);

                if (mb2.getX() == this.getMacroBlockCols()) {

                    int[][] dest = new int[4][4];
                    for (int b = 0; b < 4; b++) {
                        for (int a = 0; a < 4; a++) {
                            if (mb2.getY() < 0) {
                                dest[a][b] = 127;
                            }
                            else {
                                dest[a][b] = this.getMacroBlock(mb.getX(), mb.getY() - 1).getSubBlock(SubBlock.Plane.Y1, 3, 3).getRecon()[3][3];
                            }
                        }
                    }
                    r = new SubBlock(mb2, null, null, SubBlock.Plane.Y1);
                    r.setDest(dest);
                }

                return r;
            }
            //not right edge or top row
            else if (y > 0 && x < 3) {
                r = mb.getSubBlock(plane, x + 1, y - 1);
                return r;
            }
            //else use top right
            else {
                SubBlock sb2 = mb.getSubBlock(sb.getPlane(), 3, 0);
                return this.getAboveRightSubBlock(sb2, plane);
            }
        }
        else {
            // TODO
            throw new IllegalArgumentException("bad input: getAboveRightSubBlock()");
        }
    }

SubBlock getAboveSubBlock(SubBlock sb, SubBlock.Plane plane) {
        SubBlock above = sb.getAbove();

        if (above == null) {
            MacroBlock mb = sb.getMacroBlock();
            int x = mb.getSubblockX(sb);

            MacroBlock mb2 = getMacroBlock(mb.getX(), mb.getY() - 1);
            //TODO: SPLIT
            if (plane == SubBlock.Plane.Y2 && mb2.getYMode() == Globals.B_PRED) {
                mb2 = lastNonBPredMacroBlockByColumn[mb.getX() + 1];
            }

            above = mb2.getBottomSubBlock(x, sb.getPlane());
        }

        return above;
    }

SubBlock getLeftSubBlock(SubBlock sb, SubBlock.Plane plane) {
        SubBlock r = sb.getLeft();
        if (r == null) {
            MacroBlock mb = sb.getMacroBlock();
            int y = mb.getSubblockY(sb);
            MacroBlock mb2 = getMacroBlock(mb.getX() - 1, mb.getY());
            //TODO: SPLIT

            while (plane == SubBlock.Plane.Y2 && mb2.getYMode() == Globals.B_PRED) {
                mb2 = getMacroBlock(mb2.getX() - 1, mb2.getY());
            }

            r = mb2.getRightSubBlock(y, sb.getPlane());
        }

        return r;
    }

