/**
 * Tests for {@link SubBlock#predict(VP8Frame)}.
 *
 * <p>The block under test is the interior sub-block at (1, 1) of a macro block.
 * Its above, left, above-left and above-right neighbours are all sub-blocks of
 * the same macro block, which lets each prediction input be supplied directly
 * without relying on frame-window bookkeeping.</p>
 */
class SubBlockPredictTests {
    private static final int[] ABOVE = {10, 20, 30, 40};
    private static final int[] LEFT = {50, 60, 70, 80};
    private static final int[] ABOVE_RIGHT = {110, 120, 130, 140};
    private static final int ABOVE_LEFT = 90;

    private VP8Frame frame;
    private SubBlock target;
    private SubBlock above;
    private SubBlock left;
    private SubBlock aboveLeft;
    private SubBlock aboveRight;

    @BeforeEach
    void setUp() throws IOException {
        frame = new VP8Frame(
                new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0])), false);

        MacroBlock macroBlock = new MacroBlock(1, 1, false);
        target = macroBlock.getYSubBlock(1, 1);
        above = macroBlock.getYSubBlock(1, 0);
        left = macroBlock.getYSubBlock(0, 1);
        aboveLeft = macroBlock.getYSubBlock(0, 0);
        aboveRight = macroBlock.getYSubBlock(2, 0);
    }

    @Test
    void predictsDcFromAboveAndLeftSamples() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_DC_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {45, 45, 45, 45},
                {45, 45, 45, 45},
                {45, 45, 45, 45},
                {45, 45, 45, 45}
        });
    }

    @Test
    void predictsTrueMotionAndClampsNegativeSamples() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_TM_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {0, 0, 0, 0},
                {0, 0, 0, 10},
                {0, 0, 10, 20},
                {0, 10, 20, 30}
        });
    }

    @Test
    void predictsVerticalFromFilteredAboveSamples() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_VE_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {33, 33, 33, 33},
                {20, 20, 20, 20},
                {30, 30, 30, 30},
                {55, 55, 55, 55}
        });
    }

    @Test
    void predictsHorizontalFromFilteredLeftSamples() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_HE_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {63, 60, 70, 78},
                {63, 60, 70, 78},
                {63, 60, 70, 78},
                {63, 60, 70, 78}
        });
    }

    @Test
    void predictsLeftDownDiagonal() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_LD_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {20, 30, 55, 95},
                {30, 55, 95, 120},
                {55, 95, 120, 130},
                {95, 120, 130, 138}
        });
    }

    @Test
    void predictsRightDownDiagonal() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_RD_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {60, 63, 60, 70},
                {33, 60, 63, 60},
                {20, 33, 60, 63},
                {30, 20, 33, 60}
        });
    }

    @Test
    void predictsVerticalRightDiagonal() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_VR_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {50, 60, 63, 60},
                {15, 33, 50, 60},
                {25, 20, 15, 33},
                {35, 30, 25, 20}
        });
    }

    @Test
    void predictsVerticalLeftDiagonal() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_VL_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {15, 20, 25, 30},
                {25, 30, 35, 55},
                {35, 55, 75, 95},
                {75, 95, 120, 130}
        });
    }

    @Test
    void predictsHorizontalDownDiagonal() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_HD_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {70, 55, 65, 75},
                {60, 63, 60, 70},
                {33, 70, 55, 65},
                {20, 60, 63, 60}
        });
    }

    @Test
    void predictsHorizontalUpDiagonal() {
        useReconstructedNeighbours();
        target.setMode(Globals.B_HU_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {55, 65, 75, 80},
                {60, 70, 78, 80},
                {65, 75, 80, 80},
                {70, 78, 80, 80}
        });
    }

    @Test
    void trueMotionClampsPredictionsAbove255() {
        setAboveReconstruction(new int[]{255, 255, 255, 255});
        setLeftReconstruction(new int[]{255, 255, 255, 255});
        setAboveLeftReconstruction(0);
        target.setMode(Globals.B_TM_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {255, 255, 255, 255},
                {255, 255, 255, 255},
                {255, 255, 255, 255},
                {255, 255, 255, 255}
        });
    }

    @Test
    void usesAboveBorderWhenNeitherNeighbourWasReconstructed() {
        int[] aboveSamples = {200, 210, 220, 230};
        above.setPredict(aboveSamples(aboveSamples));
        left.setPredict(leftSamples(LEFT));
        target.setMode(Globals.B_TM_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {123, 133, 143, 153},
                {133, 143, 153, 163},
                {143, 153, 163, 173},
                {153, 163, 173, 183}
        });
    }

    @Test
    void usesAboveBorderWhenOnlyLeftWasReconstructed() {
        int[] aboveSamples = {200, 210, 220, 230};
        above.setPredict(aboveSamples(aboveSamples));
        setLeftReconstruction(LEFT);
        target.setMode(Globals.B_TM_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {123, 133, 143, 153},
                {133, 143, 153, 163},
                {143, 153, 163, 173},
                {153, 163, 173, 183}
        });
    }

    @Test
    void usesLeftBorderWhenAboveWasReconstructed() {
        int[] aboveSamples = {200, 210, 220, 230};
        setAboveReconstruction(aboveSamples);
        left.setPredict(leftSamples(LEFT));
        target.setMode(Globals.B_TM_PRED);

        target.predict(frame);

        assertMatrix(new int[][]{
                {121, 131, 141, 151},
                {131, 141, 151, 161},
                {141, 151, 161, 171},
                {151, 161, 171, 181}
        });
    }

    @Test
    void rejectsUnknownPredictionMode() {
        useReconstructedNeighbours();
        target.setMode(10);

        AssertionError error = assertThrows(AssertionError.class, () -> target.predict(frame));

        assertEquals("TODO mode: 10", error.getMessage());
    }

    private void useReconstructedNeighbours() {
        setAboveReconstruction(ABOVE);
        setLeftReconstruction(LEFT);
        setAboveLeftReconstruction(ABOVE_LEFT);
        setAboveRightReconstruction(ABOVE_RIGHT);
    }

    private void setAboveReconstruction(int[] samples) {
        above.setDest(aboveSamples(samples));
    }

    private void setLeftReconstruction(int[] samples) {
        left.setDest(leftSamples(samples));
    }

    private void setAboveLeftReconstruction(int sample) {
        int[][] matrix = new int[4][4];
        matrix[3][3] = sample;
        aboveLeft.setDest(matrix);
    }

    private void setAboveRightReconstruction(int[] samples) {
        aboveRight.setDest(aboveSamples(samples));
    }

    private static int[][] aboveSamples(int[] samples) {
        int[][] matrix = new int[4][4];
        for (int x = 0; x < 4; x++) {
            matrix[x][3] = samples[x];
        }
        return matrix;
    }

    private static int[][] leftSamples(int[] samples) {
        int[][] matrix = new int[4][4];
        for (int y = 0; y < 4; y++) {
            matrix[3][y] = samples[y];
        }
        return matrix;
    }

    private void assertMatrix(int[][] expected) {
        int[][] actual = target.getPredict();
        assertEquals(4, actual.length);
        for (int x = 0; x < 4; x++) {
            assertEquals(4, actual[x].length);
            assertArrayEquals(expected[x], actual[x], "column x=" + x);
        }
    }
}

