package com.twelvemonkeys.imageio.plugins.webp.vp8;

import com.twelvemonkeys.imageio.util.ProgressListenerBase;
import org.junit.jupiter.api.Test;

import javax.imageio.ImageReadParam;
import javax.imageio.stream.ImageInputStream;
import javax.imageio.stream.MemoryCacheImageInputStream;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.awt.image.WritableRaster;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link VP8Frame#decode(java.awt.image.WritableRaster, javax.imageio.ImageReadParam)}.
 */
public class VP8FrameDecodeTests {

    private static final String RESOURCE_BASE = "/webp/";

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static byte[] readResource(String name) throws IOException {
        try (InputStream in = VP8FrameDecodeTests.class.getResourceAsStream(RESOURCE_BASE + name)) {
            assertNotNull(in, "Missing test resource: " + RESOURCE_BASE + name);

            ByteArrayOutputStream out = new ByteArrayOutputStream();
            byte[] buffer = new byte[8192];
            int read;
            while ((read = in.read(buffer)) != -1) {
                out.write(buffer, 0, read);
            }

            return out.toByteArray();
        }
    }

    /**
     * Extracts the payload of the first {@code VP8 } (lossy) chunk from a RIFF/WEBP file.
     */
    private static byte[] extractVp8Payload(byte[] webpFile) {
        assertEquals("RIFF", new String(webpFile, 0, 4, StandardCharsets.US_ASCII), "Not a RIFF file");
        assertEquals("WEBP", new String(webpFile, 8, 4, StandardCharsets.US_ASCII), "Not a WEBP file");
        assertEquals("VP8 ", new String(webpFile, 12, 4, StandardCharsets.US_ASCII), "Expected a lossy 'VP8 ' chunk");

        int length = (webpFile[16] & 0xff)
                | ((webpFile[17] & 0xff) << 8)
                | ((webpFile[18] & 0xff) << 16)
                | ((webpFile[19] & 0xff) << 24);

        assertTrue(length > 0, "VP8 chunk must not be empty");
        assertTrue(20 + length <= webpFile.length, "VP8 chunk exceeds file size");

        return Arrays.copyOfRange(webpFile, 20, 20 + length);
    }

    private static byte[] vp8Payload(String resourceName) throws IOException {
        return extractVp8Payload(readResource(resourceName));
    }

    private static ImageInputStream stream(byte[] bytes) {
        return new MemoryCacheImageInputStream(new ByteArrayInputStream(bytes));
    }

    /** Width as encoded in the VP8 key frame header (bytes 6..7, little endian, 14 bits). */
    private static int headerWidth(byte[] payload) {
        return ((payload[6] & 0xff) | ((payload[7] & 0xff) << 8)) & 0x3fff;
    }

    /** Height as encoded in the VP8 key frame header (bytes 8..9, little endian, 14 bits). */
    private static int headerHeight(byte[] payload) {
        return ((payload[8] & 0xff) | ((payload[9] & 0xff) << 8)) & 0x3fff;
    }

    private static BufferedImage newImage(int width, int height) {
        return new BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR);
    }

    private static boolean containsNonZero(int[] samples) {
        for (int sample : samples) {
            if (sample != 0) {
                return true;
            }
        }

        return false;
    }

    // ------------------------------------------------------------------
    // Invalid input / non key frame
    // ------------------------------------------------------------------

    @Test
    public void decodeReturnsFalseForInterFrame() throws IOException {
        // Bit 0 set == inter frame (frame type != 0). WebP only allows key frames.
        byte[] payload = {0x01};

        VP8Frame frame = new VP8Frame(stream(payload), false);

        assertFalse(frame.decode(null, null), "Inter frames should not be decoded");

        // The frame type is still recorded before the early return, and segment quants are initialised.
        assertEquals(1, frame.getFrameType());
        assertNotNull(frame.getSegmentQuants());
    }

    @Test
    public void decodeReturnsFalseForInterFrameEvenWithRasterAndParam() throws IOException {
        byte[] payload = {(byte) 0xFF}; // bit 0 set, every other bit set as well

        VP8Frame frame = new VP8Frame(stream(payload), false);
        BufferedImage image = newImage(1, 1);

        assertFalse(frame.decode(image.getRaster(), new ImageReadParam()));

        assertEquals(1, frame.getFrameType());
        // Nothing was decoded, so no dimensions / macro blocks have been computed.
        assertEquals(0, frame.getWidth());
        assertEquals(0, frame.getHeight());
        assertEquals(0, frame.getMacroBlockCols());
        assertEquals(0, frame.getMacroBlockRows());
    }

    @Test
    public void decodeThrowsEofForEmptyStream() throws IOException {
        VP8Frame frame = new VP8Frame(stream(new byte[0]), false);

        assertThrows(EOFException.class, () -> frame.decode(null, null));
    }

    @Test
    public void decodeThrowsEofWhenTruncatedAfterFrameType() throws IOException {
        // Only the frame-type/tag byte is present; the key frame header that follows is missing.
        byte[] payload = {0x00};

        VP8Frame frame = new VP8Frame(stream(payload), false);

        assertThrows(EOFException.class, () -> frame.decode(null, null));
    }

    @Test
    public void decodeThrowsEofWhenTruncatedInsideHeader() throws IOException {
        // Key frame byte plus the two extra first-partition-size bytes, but no start code/dimensions.
        byte[] payload = {0x00, 0x00, 0x00};

        VP8Frame frame = new VP8Frame(stream(payload), false);

        assertThrows(EOFException.class, () -> frame.decode(null, null));
    }

    // ------------------------------------------------------------------
    // Successful decoding
    // ------------------------------------------------------------------

    @Test
    public void decodeSinglePixelImage() throws IOException {
        byte[] payload = vp8Payload("small_1x1.webp");

        int width = headerWidth(payload);
        int height = headerHeight(payload);
        assertEquals(1, width);
        assertEquals(1, height);

        VP8Frame frame = new VP8Frame(stream(payload), false);
        BufferedImage image = newImage(width, height);
        WritableRaster raster = image.getRaster();
        int[] before = raster.getPixels(0, 0, width, height, (int[]) null);

        assertTrue(frame.decode(raster, null), "Key frame should be decoded");

        assertEquals(0, frame.getFrameType(), "Frame type should be key frame");
        assertEquals(width, frame.getWidth());
        assertEquals(height, frame.getHeight());

        // 1x1 is rounded up to a single 16x16 macro block.
        assertEquals(1, frame.getMacroBlockCols());
        assertEquals(1, frame.getMacroBlockRows());

        assertNotNull(frame.getSegmentQuants());
        assertNotNull(frame.getTokenBoolDecoder());

        // The decoder must actually write pixel data into the supplied raster.
        int[] after = raster.getPixels(0, 0, width, height, (int[]) null);
        assertFalse(Arrays.equals(before, after), "Decoding should modify the destination raster");
        assertTrue(containsNonZero(after), "Decoded pixels should not all be zero");
    }

    @Test
    public void decodeKeyFrameWithExplicitParam() throws IOException {
        byte[] payload = vp8Payload("small_1x1.webp");

        VP8Frame frame = new VP8Frame(stream(payload), false);
        BufferedImage image = newImage(headerWidth(payload), headerHeight(payload));

        // A non-null param without a source region must behave like a null param.
        assertTrue(frame.decode(image.getRaster(), new ImageReadParam()));

        assertEquals(0, frame.getFrameType());
        assertEquals(1, frame.getWidth());
        assertEquals(1, frame.getHeight());
        assertEquals(1, frame.getMacroBlockCols());
        assertEquals(1, frame.getMacroBlockRows());
    }

    @Test
    public void decodeRoundsWidthUpToMacroBlockBoundary() throws IOException {
        byte[] payload = vp8Payload("small_13x1.webp");

        int width = headerWidth(payload);
        int height = headerHeight(payload);
        assertEquals(13, width);
        assertEquals(1, height);

        VP8Frame frame = new VP8Frame(stream(payload), false);
        BufferedImage image = newImage(width, height);

        assertTrue(frame.decode(image.getRaster(), null));

        assertEquals(13, frame.getWidth());
        assertEquals(1, frame.getHeight());
        // 13 wide rounds up to a single 16-wide macro block.
        assertEquals(1, frame.getMacroBlockCols());
        assertEquals(1, frame.getMacroBlockRows());
    }

    @Test
    public void decodeComputesMultipleMacroBlockColumns() throws IOException {
        byte[] payload = vp8Payload("small_31x13.webp");

        int width = headerWidth(payload);
        int height = headerHeight(payload);
        assertEquals(31, width);
        assertEquals(13, height);

        VP8Frame frame = new VP8Frame(stream(payload), false);
        BufferedImage image = newImage(width, height);

        assertTrue(frame.decode(image.getRaster(), null));

        assertEquals(31, frame.getWidth());
        assertEquals(13, frame.getHeight());
        // 31 -> 32 = 2 macro block columns, 13 -> 16 = 1 macro block row.
        assertEquals(2, frame.getMacroBlockCols());
        assertEquals(1, frame.getMacroBlockRows());

        // The whole image must have been rendered into the destination raster.
        int[] decoded = image.getRaster().getPixels(0, 0, width, height, (int[]) null);
        assertTrue(containsNonZero(decoded), "Decoded pixels should not all be zero");
    }

    // ------------------------------------------------------------------
    // Observable side effects
    // ------------------------------------------------------------------

    @Test
    public void decodeFiresProgressToCompletion() throws IOException {
        byte[] payload = vp8Payload("small_31x13.webp");
        VP8Frame frame = new VP8Frame(stream(payload), false);

        final List<Float> progress = new ArrayList<>();
        frame.setProgressListener(new ProgressListenerBase() {
            @Override
            public void imageProgress(javax.imageio.ImageReader source, float percentageDone) {
                progress.add(percentageDone);
            }
        });

        BufferedImage image = newImage(headerWidth(payload), headerHeight(payload));

        assertTrue(frame.decode(image.getRaster(), null));

        assertEquals(1, progress.size(), "Progress should be reported once per macro block row");
        assertEquals(100.0f, progress.get(0), 0.0001f, "Single macro block row should report 100%");
    }

    @Test
    public void decodeFiresProgressForEveryMacroBlockRow() throws IOException {
        byte[] payload = vp8Payload("test.webp");
        VP8Frame frame = new VP8Frame(stream(payload), false);

        final List<Float> progress = new ArrayList<>();
        frame.setProgressListener(new ProgressListenerBase() {
            @Override
            public void imageProgress(javax.imageio.ImageReader source, float percentageDone) {
                progress.add(percentageDone);
            }
        });

        int width = headerWidth(payload);
        int height = headerHeight(payload);
        BufferedImage image = newImage(width, height);

        assertTrue(frame.decode(image.getRaster(), null));

        int expectedRows = frame.getMacroBlockRows();
        assertTrue(expectedRows > 0);
        assertEquals(expectedRows, progress.size(), "Progress should be reported once per macro block row");

        // Progress must be monotonically increasing and end at 100%.
        float previous = -1.0f;
        for (Float value : progress) {
            assertTrue(value > previous, "Progress should increase monotonically: " + progress);
            previous = value;
        }
        assertEquals(100.0f, progress.get(progress.size() - 1), 0.0001f);
    }

    @Test
    public void decodeDoesNotReportProgressWithoutListener() throws IOException {
        byte[] payload = vp8Payload("small_1x1.webp");

        VP8Frame frame = new VP8Frame(stream(payload), false);
        BufferedImage image = newImage(headerWidth(payload), headerHeight(payload));

        // No listener is registered; this must not throw a NullPointerException.
        assertTrue(frame.decode(image.getRaster(), null));
    }

    @Test
    public void decodeExposesSameFrameInstanceForTokenDecoder() throws IOException {
        byte[] payload = vp8Payload("small_1x1.webp");
        VP8Frame frame = new VP8Frame(stream(payload), false);
        BufferedImage image = newImage(headerWidth(payload), headerHeight(payload));

        assertTrue(frame.decode(image.getRaster(), null));

        BoolDecoder decoder = frame.getTokenBoolDecoder();
        assertNotNull(decoder);
        assertSame(decoder, frame.getTokenBoolDecoder());
    }

    @Test
    public void decodeHonoursSourceRegion() throws IOException {
        byte[] payload = vp8Payload("small_31x13.webp");

        int width = headerWidth(payload);
        int height = headerHeight(payload);

        // Decode the full image for reference.
        VP8Frame fullFrame = new VP8Frame(stream(payload), false);
        BufferedImage fullImage = newImage(width, height);
        assertTrue(fullFrame.decode(fullImage.getRaster(), null));

        // Now decode only the right-hand part of the image into a smaller raster.
        int regionX = 16;
        int regionWidth = width - regionX;
        VP8Frame regionFrame = new VP8Frame(stream(payload), false);
        BufferedImage regionImage = newImage(regionWidth, height);

        ImageReadParam param = new ImageReadParam();
        param.setSourceRegion(new Rectangle(regionX, 0, regionWidth, height));

        assertTrue(regionFrame.decode(regionImage.getRaster(), param));

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < regionWidth; x++) {
                assertEquals(fullImage.getRGB(regionX + x, y), regionImage.getRGB(x, y),
                        "Pixel (" + x + "," + y + ") in region should equal full image pixel ("
                                + (regionX + x) + "," + y + ")");
            }
        }
    }

    @Test
    public void decodeHonoursSourceSubsampling() throws IOException {
        byte[] payload = vp8Payload("small_31x13.webp");

        int width = headerWidth(payload);
        int height = headerHeight(payload);

        // Decode the full image for reference.
        VP8Frame fullFrame = new VP8Frame(stream(payload), false);
        BufferedImage fullImage = newImage(width, height);
        assertTrue(fullFrame.decode(fullImage.getRaster(), null));

        // Decode every second column.
        int widthStep = 2;
        int subsampledWidth = (width + widthStep - 1) / widthStep;
        VP8Frame subsampledFrame = new VP8Frame(stream(payload), false);
        BufferedImage subsampledImage = newImage(subsampledWidth, height);

        ImageReadParam param = new ImageReadParam();
        param.setSourceSubsampling(widthStep, 1, 0, 0);

        assertTrue(subsampledFrame.decode(subsampledImage.getRaster(), param));

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < subsampledWidth; x++) {
                int sourceX = x * widthStep;
                if (sourceX >= width) {
                    break;
                }
                assertEquals(fullImage.getRGB(sourceX, y), subsampledImage.getRGB(x, y),
                        "Subsampled pixel (" + x + "," + y + ") should equal full image pixel ("
                                + sourceX + "," + y + ")");
            }
        }
    }
}
